// nsh grammar. NOTE: the order of rule declarations matters because pest
// sorts expected rules by declaration order in error messages.

WHITESPACE = _{ " " | "\t" | "\r" | ("\\" ~ "\n") }
COMMENT = _{ "#" ~ (!"\n" ~ ANY)* }

// ---------------------------------------------------------------------------
// Arithmetic expressions ($((...)) and for ((...)))
// ---------------------------------------------------------------------------
var_name = @{ (ASCII_ALPHANUMERIC | "_")+ }
num = @{ ASCII_DIGIT+ }
comp_op = { "==" | "!=" | "<=" | ">=" | "<" | ">" }
assign_op = { "=" }
arith_op = { "+" | "-" }
factor_op = { "*" | "/" }
sign = { "+" | "-" }
postfix_op = { "++" | "--" }
primary = _{ num | var_name | param_ex_span }
factor = { "(" ~ assign ~ ")" | sign? ~ primary ~ postfix_op? }
term = { factor ~ (factor_op ~ term)? }
arith = { term ~ (arith_op ~ arith)? }
comp = { arith ~ (comp_op ~ assign)? }
assign = { var_name ~ assign_op ~ assign | comp }

arith_for_exprs = { "((" ~ assign ~ ";" ~ assign ~ ";" ~ assign ~ "))" }

// ---------------------------------------------------------------------------
// Words
// ---------------------------------------------------------------------------
word = ${ (tilde_span | span) ~ span* }
span = _{
    literal_span
    | any_string_span
    | any_char_span
    | command_span
    | proc_subst_span
    | backtick_span
    | expr_span
    | param_ex_span
    | param_span
    | double_quoted_span
    | single_quoted_span
}

escaped_char = @{ "\\" ~ ANY? }
unescaped_char = @{ !(" " | "\t" | "\r" | "\n" | "{" | "}" | "(" | ")" | "&" | ";" | "<" | ">" | "|" | "*" | "?" | "$" | "'" | "\"" | "`" | "\\") ~ ANY }
literal_span = ${ (escaped_char | unescaped_char)+ }
tilde_span = ${ "~" ~ tilde_user? }
tilde_user = @{ (!(" " | "\t" | "\r" | "\n" | "/" | "*" | "?" | "$" | "&" | ";" | "|" | "<" | ">" | "`" | "'" | "\"" | "{" | "}" | "(" | ")") ~ ANY)+ }
any_string_span = { "*" }
any_char_span = { "?" }
command_span = !{ "$(" ~ compound_list ~ ")" }
proc_subst_direction = { "<" | ">" }
proc_subst_span = !{ proc_subst_direction ~ "(" ~ compound_list ~ ")" }
backtick_span = !{ "`" ~ compound_list ~ "`" }
expr_span = !{ "$((" ~ assign ~ "))" }
param_ex_span = ${ "$" ~ ("{" ~ length_op? ~ param_name ~ index? ~ param_op? ~ "}" | var_name) }
length_op = { "#" }
param_name = _{ var_name | special_var }
special_var = { "?" | "!" | "#" | "$" | "@" | "*" | "-" }
index = !{ "[" ~ assign ~ "]" }
param_op = !{ param_op_default | param_op_assign | param_op_subst_all | param_op_subst }
param_op_default = { (":-" | "-") ~ word? }
param_op_assign = { (":=" | "=") ~ word? }
param_op_subst_all = { "//" ~ pattern_word? ~ ("/" ~ word?)? }
param_op_subst = { "/" ~ pattern_word? ~ ("/" ~ word?)? }
pattern_word = ${ pattern_span+ }
pattern_span = _{ pattern_literal_span | any_string_span | any_char_span | command_span | backtick_span | expr_span | param_ex_span | param_span | double_quoted_span | single_quoted_span }
pattern_literal_span = ${ (escaped_char | pattern_unescaped_char)+ }
pattern_unescaped_char = @{ !(" " | "\t" | "\r" | "\n" | "{" | "}" | "(" | ")" | "&" | ";" | "<" | ">" | "|" | "*" | "?" | "$" | "'" | "\"" | "`" | "\\" | "/") ~ ANY }
param_span = ${ "$" ~ (special_var | var_name) }
literal_in_double_quoted_span = @{ (("\\" ~ ANY) | (!("\"" | "$" | "`") ~ ANY))+ }
double_quoted_span = ${ "\"" ~ (command_span | backtick_span | expr_span | param_ex_span | param_span | literal_in_double_quoted_span)* ~ "\"" }
literal_in_single_quoted_span = @{ (("\\" ~ ANY) | (!"'" ~ ANY))+ }
single_quoted_span = ${ "'" ~ literal_in_single_quoted_span? ~ "'" }

// ---------------------------------------------------------------------------
// Assignments
// ---------------------------------------------------------------------------
initializer = { "(" ~ word* ~ ")" }
assignment_value = _{ initializer | assignment_word }
assignment_word = ${ (tilde_span | span) ~ span* }
assignment = { var_name ~ "=" ~ assignment_value }

// ---------------------------------------------------------------------------
// Newlines / separators / lists
// ---------------------------------------------------------------------------
normal_newline = { "\n" }
newline = _{ "\n" ~ heredoc_body? }

// ---------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------
command = {
    if_command
    | while_command
    | arith_for_command
    | for_command
    | case_command
    | function_definition
    | group
    | subshell
    | local_definition
    | return_command
    | break_command
    | continue_command
    | simple_command
}

simple_command = { assignment* ~ !keyword ~ (redirect | word)+ }
keyword = _{ ("if" | "then" | "elif" | "else" | "fi" | "while" | "do" | "done" | "for" | "in" | "case" | "esac" | "local" | "return" | "break" | "continue" | "function") ~ !unescaped_char }

redirect = _{ redirect_direction ~ (redirect_to_fd | word) | heredoc }
redirect_direction = { ASCII_DIGIT* ~ (">>" | ">" | "<") }
redirect_to_fd = ${ "&" ~ ASCII_DIGIT* }
heredoc = { "<<" ~ heredoc_marker }
heredoc_marker = @{ PUSH((ASCII_ALPHANUMERIC | "_" | "-" | ".")+) }
heredoc_body = { (!heredoc_end ~ heredoc_line)* ~ heredoc_end }
heredoc_line = { word* ~ "\n" }
heredoc_end = _{ POP ~ ("\n" | EOI) }

if_command = {
    "if" ~ compound_list ~ "then" ~ compound_list ~ elif_part* ~ else_part? ~ "fi"
}
elif_part = { "elif" ~ compound_list ~ "then" ~ compound_list }
else_part = { "else" ~ compound_list }

while_command = { "while" ~ compound_list ~ "do" ~ compound_list ~ "done" }
for_command = { "for" ~ var_name ~ "in" ~ word* ~ for_sep ~ "do" ~ compound_list ~ "done" }
for_sep = _{ ";" ~ normal_newline* | normal_newline+ }
arith_for_command = { "for" ~ arith_for_exprs ~ for_sep ~ "do" ~ compound_list ~ "done" }
case_command = { "case" ~ word ~ "in" ~ normal_newline* ~ case_item* ~ "esac" }
case_item = { !"esac" ~ word ~ ("|" ~ word)* ~ ")" ~ compound_list ~ (";;" ~ normal_newline* | &"esac") }
function_definition = { var_name ~ "(" ~ ")" ~ normal_newline* ~ (group | subshell) }
group = { "{" ~ compound_list ~ "}" }
subshell = { "(" ~ compound_list ~ ")" }
local_definition = { "local" ~ (assignment | var_name)+ }
return_command = { "return" ~ num? }
break_command = { "break" }
continue_command = { "continue" }

pipeline = { command ~ ((!"||" ~ "|") ~ normal_newline* ~ command)* }
and_or_list_sep = { "&&" | "||" }
and_or_list = { pipeline ~ (and_or_list_sep ~ normal_newline* ~ pipeline)* }
compound_list_sep = { (!";;" ~ ";") | (!"&&" ~ "&") | newline }
compound_list = { compound_list_sep* ~ and_or_list? ~ (compound_list_sep ~ normal_newline* ~ and_or_list?)* }

script = _{ SOI ~ compound_list ~ EOI }
EOF
