//! Parser: converts the pest parse tree into an AST.
use pest::iterators::Pair;
use pest::Parser;
use pest_derive::Parser;

#[derive(Parser)]
#[grammar = "shell.pest"]
pub struct ShellParser;

pub type ParseError = pest::error::Error<Rule>;

#[derive(Debug, Clone, PartialEq)]
pub enum RunIf {
    Always,
    Success,
    Failure,
}

#[derive(Debug, Clone)]
pub struct Ast {
    pub terms: Vec<Term>,
}

#[derive(Debug, Clone)]
pub struct Term {
    pub code: String,
    pub pipelines: Vec<Pipeline>,
    pub background: bool,
}

#[derive(Debug, Clone)]
pub struct Pipeline {
    pub run_if: RunIf,
    pub commands: Vec<Command>,
}

#[derive(Debug, Clone)]
pub enum RedirectionDirection {
    Input,
    Output,
    Append,
}

#[derive(Debug, Clone)]
pub enum RedirectionType {
    File(Word),
    Fd(i32),
    HereDoc(HereDoc),
    /// A heredoc which appears in a nested context (not resolved).
    UnresolvedHereDoc(usize),
}

#[derive(Debug, Clone)]
pub struct HereDoc {
    pub lines: Vec<Vec<Word>>,
}

#[derive(Debug, Clone)]
pub struct Redirection {
    pub fd: i32,
    pub direction: RedirectionDirection,
    pub target: RedirectionType,
}

#[derive(Debug, Clone)]
pub enum Initializer {
    Array(Vec<Word>),
    String(Word),
}

#[derive(Debug, Clone)]
pub struct Assignment {
    pub name: String,
    pub initializer: Initializer,
}

#[derive(Debug, Clone)]
pub enum LocalDeclaration {
    Assignment(Assignment),
    Name(String),
}

#[derive(Debug, Clone)]
pub struct CaseItem {
    pub patterns: Vec<Word>,
    pub body: Vec<Term>,
}

#[derive(Debug, Clone)]
pub struct ElIf {
    pub condition: Vec<Term>,
    pub then_part: Vec<Term>,
}

#[derive(Debug, Clone)]
pub enum Command {
    SimpleCommand {
        argv: Vec<Word>,
        redirects: Vec<Redirection>,
        assignments: Vec<Assignment>,
    },
    Assignment {
        assignments: Vec<Assignment>,
    },
    If {
        condition: Vec<Term>,
        then_part: Vec<Term>,
        elif_parts: Vec<ElIf>,
        else_part: Option<Vec<Term>>,
    },
    While {
        condition: Vec<Term>,
        body: Vec<Term>,
    },
    For {
        var_name: String,
        words: Vec<Word>,
        body: Vec<Term>,
    },
    ArithFor {
        init: Expr,
        cond: Expr,
        update: Expr,
        body: Vec<Term>,
    },
    Case {
        word: Word,
        cases: Vec<CaseItem>,
    },
    FunctionDef {
        name: String,
        body: Box<Command>,
    },
    LocalDef {
        declarations: Vec<LocalDeclaration>,
    },
    Group {
        terms: Vec<Term>,
    },
    SubShellGroup {
        terms: Vec<Term>,
    },
    Return {
        status: Option<i32>,
    },
    Break,
    Continue,
}

#[derive(Debug, Clone)]
pub enum ExpansionOp {
    Length,
    GetOrEmpty,
    GetOrDefault(Word),
    GetNullableOrDefault(Word),
    GetOrDefaultAndAssign(Word),
    GetNullableOrDefaultAndAssign(Word),
    Subst {
        pattern: Word,
        replacement: Word,
        replace_all: bool,
    },
}

#[derive(Debug, Clone)]
pub enum BinaryExpr {
    Add,
    Sub,
    Mul,
    Div,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

#[derive(Debug, Clone)]
pub enum Expr {
    Literal(i32),
    /// The sign was dropped for non-literals in the original implementation.
    Binary(BinaryExpr, Box<Expr>, Box<Expr>),
    Assign { name: String, rhs: Box<Expr> },
    Parameter { name: String },
    Inc(String),
    Dec(String),
}

#[derive(Debug, Clone)]
pub enum Span {
    Literal(String),
    /// A literal character which was escaped (e.g. `\/`); treated as literal
    /// text but not as a separator.
    Tilde(Option<String>),
    AnyString,
    AnyChar,
    Parameter {
        name: String,
        op: ExpansionOp,
        quoted: bool,
    },
    ArrayParameter {
        name: String,
        index: Expr,
        quoted: bool,
    },
    ArithExpr {
        expr: Expr,
    },
    Command {
        body: Vec<Term>,
        quoted: bool,
    },
    ProcSubst {
        body: Vec<Term>,
        output: bool,
    },
}

#[derive(Debug, Clone)]
pub struct Word(pub Vec<Span>);

/// A panic which mirrors the original implementation's panics in the parser.
pub fn parser_panic(location: &str, msg: &str) -> ! {
    crate::panic_at(location, msg)
}

struct Builder {
    heredocs: Vec<HereDoc>,
    heredoc_index: usize,
    /// Depth of nesting (0 = top-level compound list).
    depth: usize,
}

pub fn parse(script: &str) -> Result<Ast, Box<ParseError>> {
    let pairs = ShellParser::parse(Rule::script, script).map_err(Box::new)?;
    let mut builder = Builder {
        heredocs: Vec::new(),
        heredoc_index: 0,
        depth: 0,
    };

    // Collect all heredoc bodies in document order.
    let mut collected = Vec::new();
    for pair in pairs.clone().flatten() {
        if pair.as_rule() == Rule::heredoc_body {
            collected.push(builder.build_heredoc_body(pair));
        }
    }
    builder.heredocs = collected;

    let mut terms = Vec::new();
    for pair in pairs {
        if pair.as_rule() == Rule::compound_list {
            terms = builder.build_compound_list(pair);
        }
    }
    Ok(Ast { terms })
}

/// Parse an alias definition (`name=value`).
#[derive(Parser)]
#[grammar = "alias.pest"]
pub struct AliasParser;

pub fn parse_alias(text: &str) -> Result<(String, String), pest::error::Error<alias_rule::Rule>> {
    let mut pairs = AliasParser::parse(alias_rule::Rule::alias, text)?;
    let alias = pairs.next().unwrap();
    let mut name = String::new();
    let mut body = String::new();
    for inner in alias.into_inner() {
        match inner.as_rule() {
            alias_rule::Rule::name => name = inner.as_str().to_owned(),
            alias_rule::Rule::body => body = inner.as_str().to_owned(),
            _ => {}
        }
    }
    Ok((name, body))
}

pub mod alias_rule {
    pub use super::AliasParser;
    pub type Rule = <AliasParser as pest::Parser<super::AliasRuleAlias>>::Rule;
}

impl Builder {
    fn build_heredoc_body(&mut self, pair: Pair<Rule>) -> HereDoc {
        let mut lines = Vec::new();
        for line in pair.into_inner() {
            if line.as_rule() == Rule::heredoc_line {
                let mut words = Vec::new();
                for w in line.into_inner() {
                    if w.as_rule() == Rule::word {
                        words.push(self.build_word(w));
                    }
                }
                lines.push(words);
            }
        }
        HereDoc { lines }
    }

    fn build_compound_list(&mut self, pair: Pair<Rule>) -> Vec<Term> {
        let mut terms: Vec<Term> = Vec::new();
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::and_or_list => {
                    let code = inner.as_str().to_owned();
                    let pipelines = self.build_and_or_list(inner);
                    terms.push(Term {
                        code,
                        pipelines,
                        background: false,
                    });
                }
                Rule::compound_list_sep => {
                    if inner.as_str().starts_with('&') {
                        if let Some(last) = terms.last_mut() {
                            last.background = true;
                        }
                    }
                }
                _ => {}
            }
        }
        terms
    }

    fn build_nested_compound_list(&mut self, pair: Pair<Rule>) -> Vec<Term> {
        self.depth += 1;
        let terms = self.build_compound_list(pair);
        self.depth -= 1;
        terms
    }

    fn build_and_or_list(&mut self, pair: Pair<Rule>) -> Vec<Pipeline> {
        let mut pipelines = Vec::new();
        let mut run_if = RunIf::Always;
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::pipeline => {
                    let commands = self.build_pipeline(inner);
                    pipelines.push(Pipeline {
                        run_if: run_if.clone(),
                        commands,
                    });
                }
                Rule::and_or_list_sep => {
                    run_if = match inner.as_str() {
                        "&&" => RunIf::Success,
                        _ => RunIf::Failure,
                    };
                }
                _ => {}
            }
        }
        pipelines
    }

    fn build_pipeline(&mut self, pair: Pair<Rule>) -> Vec<Command> {
        let mut commands = Vec::new();
        for inner in pair.into_inner() {
            if inner.as_rule() == Rule::command {
                commands.push(self.build_command(inner));
            }
        }
        commands
    }

    fn build_command(&mut self, pair: Pair<Rule>) -> Command {
        let inner = pair.into_inner().next().unwrap();
        match inner.as_rule() {
            Rule::simple_command => self.build_simple_command(inner),
            Rule::if_command => self.build_if_command(inner),
            Rule::while_command => self.build_while_command(inner),
            Rule::for_command => self.build_for_command(inner),
            Rule::arith_for_command => self.build_arith_for_command(inner),
            Rule::case_command => self.build_case_command(inner),
            Rule::function_definition => self.build_function_definition(inner),
            Rule::group => {
                let list = inner.into_inner().next().unwrap();
                Command::Group {
                    terms: self.build_nested_compound_list(list),
                }
            }
            Rule::subshell => {
                let list = inner.into_inner().next().unwrap();
                Command::SubShellGroup {
                    terms: self.build_nested_compound_list(list),
                }
            }
            Rule::local_definition => self.build_local_definition(inner),
            Rule::return_command => {
                let mut status = None;
                for p in inner.into_inner() {
                    if p.as_rule() == Rule::num {
                        status = Some(p.as_str().parse::<i32>().unwrap_or(0));
                    }
                }
                Command::Return { status }
            }
            Rule::break_command => Command::Break,
            Rule::continue_command => Command::Continue,
            _ => unreachable!(),
        }
    }

    fn build_simple_command(&mut self, pair: Pair<Rule>) -> Command {
        let mut assignments = Vec::new();
        let mut argv: Vec<Word> = Vec::new();
        let mut redirects = Vec::new();
        let mut pending_direction: Option<(i32, RedirectionDirection)> = None;
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::assignment => assignments.push(self.build_assignment(inner)),
                Rule::word => {
                    let word = self.build_word(inner);
                    if let Some((fd, direction)) = pending_direction.take() {
                        redirects.push(Redirection {
                            fd,
                            direction,
                            target: RedirectionType::File(word),
                        });
                    } else {
                        argv.push(word);
                    }
                }
                Rule::redirect_direction => {
                    let text = inner.as_str();
                    let (fd_text, direction) = if let Some(prefix) = text.strip_suffix(">>") {
                        (prefix, RedirectionDirection::Append)
                    } else if let Some(prefix) = text.strip_suffix('>') {
                        (prefix, RedirectionDirection::Output)
                    } else {
                        (text.strip_suffix('<').unwrap_or(text), RedirectionDirection::Input)
                    };
                    let fd_text = fd_text.trim();
                    let default_fd = match direction {
                        RedirectionDirection::Input => 0,
                        _ => 1,
                    };
                    let fd = if fd_text.is_empty() {
                        default_fd
                    } else {
                        match fd_text.parse::<usize>() {
                            Ok(n) => n as i32,
                            Err(_) => default_fd,
                        }
                    };
                    pending_direction = Some((fd, direction));
                }
                Rule::redirect_to_fd => {
                    let (fd, direction) = pending_direction.take().unwrap();
                    let digits = &inner.as_str()[1..];
                    let target_fd = match digits.parse::<i32>() {
                        Ok(n) => n,
                        Err(e) => parser_panic(
                            "src/parser.rs:868:22",
                            &format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
                        ),
                    };
                    redirects.push(Redirection {
                        fd,
                        direction,
                        target: RedirectionType::Fd(target_fd),
                    });
                }
                Rule::heredoc => {
                    let index = self.heredoc_index;
                    self.heredoc_index += 1;
                    let target = if self.depth == 0 {
                        if index >= self.heredocs.len() {
                            parser_panic(
                                "src/parser.rs:1326:62",
                                &format!(
                                    "index out of bounds: the len is {} but the index is {}",
                                    self.heredocs.len(),
                                    index
                                ),
                            );
                        }
                        RedirectionType::HereDoc(self.heredocs[index].clone())
                    } else {
                        if index >= self.heredocs.len() {
                            parser_panic(
                                "src/parser.rs:1326:62",
                                &format!(
                                    "index out of bounds: the len is {} but the index is {}",
                                    self.heredocs.len(),
                                    index
                                ),
                            );
                        }
                        RedirectionType::UnresolvedHereDoc(index)
                    };
                    redirects.push(Redirection {
                        fd: 0,
                        direction: RedirectionDirection::Input,
                        target,
                    });
                }
                _ => {}
            }
        }

        if argv.is_empty() {
            Command::Assignment { assignments }
        } else {
            Command::SimpleCommand {
                argv,
                redirects,
                assignments,
            }
        }
    }

    fn build_assignment(&mut self, pair: Pair<Rule>) -> Assignment {
        let mut name = String::new();
        let mut spans = Vec::new();
        let mut initializer = None;
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::var_name => name = inner.as_str().to_owned(),
                Rule::initializer => {
                    let mut words = Vec::new();
                    for w in inner.into_inner() {
                        if w.as_rule() == Rule::word {
                            words.push(self.build_word(w));
                        }
                    }
                    initializer = Some(Initializer::Array(words));
                }
                Rule::assignment_word => {
                    let w = self.build_word(inner);
                    initializer = Some(Initializer::String(w));
                }
                _ => {
                    self.build_span(inner, &mut spans, false);
                }
            }
        }
        let initializer = match initializer {
            Some(i) => i,
            None => Initializer::String(Word(spans)),
        };
        Assignment { name, initializer }
    }

    fn build_local_definition(&mut self, pair: Pair<Rule>) -> Command {
        let mut declarations = Vec::new();
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::local_assignment => {
                    declarations.push(LocalDeclaration::Assignment(self.build_assignment(inner)))
                }
                Rule::var_name => declarations.push(LocalDeclaration::Name(inner.as_str().to_owned())),
                _ => {}
            }
        }
        Command::LocalDef { declarations }
    }

    fn build_if_command(&mut self, pair: Pair<Rule>) -> Command {
        let mut lists = Vec::new();
        let mut elif_parts = Vec::new();
        let mut else_part = None;
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::compound_list => lists.push(self.build_nested_compound_list(inner)),
                Rule::elif_part => {
                    let mut parts = Vec::new();
                    for p in inner.into_inner() {
                        if p.as_rule() == Rule::compound_list {
                            parts.push(self.build_nested_compound_list(p));
                        }
                    }
                    let then_part = parts.pop().unwrap();
                    let condition = parts.pop().unwrap();
                    elif_parts.push(ElIf { condition, then_part });
                }
                Rule::else_part => {
                    for p in inner.into_inner() {
                        if p.as_rule() == Rule::compound_list {
                            else_part = Some(self.build_nested_compound_list(p));
                        }
                    }
                }
                _ => {}
            }
        }
        let then_part = lists.pop().unwrap();
        let condition = lists.pop().unwrap();
        Command::If {
            condition,
            then_part,
            elif_parts,
            else_part,
        }
    }

    fn build_while_command(&mut self, pair: Pair<Rule>) -> Command {
        let mut lists = Vec::new();
        for inner in pair.into_inner() {
            if inner.as_rule() == Rule::compound_list {
                lists.push(self.build_nested_compound_list(inner));
            }
        }
        let body = lists.pop().unwrap();
        let condition = lists.pop().unwrap();
        Command::While { condition, body }
    }

    fn build_for_command(&mut self, pair: Pair<Rule>) -> Command {
        let mut var_name = String::new();
        let mut words = Vec::new();
        let mut body = Vec::new();
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::var_name => var_name = inner.as_str().to_owned(),
                Rule::word => words.push(self.build_word(inner)),
                Rule::compound_list => body = self.build_nested_compound_list(inner),
                _ => {}
            }
        }
        Command::For {
            var_name,
            words,
            body,
        }
    }

    fn build_arith_for_command(&mut self, pair: Pair<Rule>) -> Command {
        let mut exprs = Vec::new();
        let mut body = Vec::new();
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::arith_for_exprs => {
                    for e in inner.into_inner() {
                        if e.as_rule() == Rule::assign {
                            exprs.push(self.build_expr(e));
                        }
                    }
                }
                Rule::compound_list => body = self.build_nested_compound_list(inner),
                _ => {}
            }
        }
        let update = exprs.pop().unwrap();
        let cond = exprs.pop().unwrap();
        let init = exprs.pop().unwrap();
        Command::ArithFor {
            init,
            cond,
            update,
            body,
        }
    }

    fn build_case_command(&mut self, pair: Pair<Rule>) -> Command {
        let mut word = None;
        let mut cases = Vec::new();
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::word => word = Some(self.build_word(inner)),
                Rule::case_item => {
                    let mut patterns = Vec::new();
                    let mut body = Vec::new();
                    for p in inner.into_inner() {
                        match p.as_rule() {
                            Rule::word => patterns.push(self.build_word(p)),
                            Rule::compound_list => body = self.build_nested_compound_list(p),
                            _ => {}
                        }
                    }
                    cases.push(CaseItem { patterns, body });
                }
                _ => {}
            }
        }
        Command::Case {
            word: word.unwrap(),
            cases,
        }
    }

    fn build_function_definition(&mut self, pair: Pair<Rule>) -> Command {
        let mut name = String::new();
        let mut body = None;
        let mut newlines = 0;
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::var_name => name = inner.as_str().to_owned(),
                Rule::normal_newline => newlines += 1,
                Rule::command => {
                    if newlines > 1 {
                        parser_panic("src/parser.rs:1201:18", "internal error: entered unreachable code");
                    }
                    self.depth += 1;
                    body = Some(self.build_command(inner));
                    self.depth -= 1;
                }
                _ => {}
            }
        }
        Command::FunctionDef {
            name,
            body: Box::new(body.unwrap()),
        }
    }

    // ------------------------------------------------------------------
    // Arithmetic expressions
    // ------------------------------------------------------------------
    fn build_expr(&mut self, pair: Pair<Rule>) -> Expr {
        match pair.as_rule() {
            Rule::assign => {
                let mut inner: Vec<Pair<Rule>> = pair.into_inner().collect();
                if inner.len() == 1 {
                    return self.build_expr(inner.pop().unwrap());
                }
                // var_name assign_op assign
                let rhs = inner.pop().unwrap();
                let _op = inner.pop().unwrap();
                let name = inner.pop().unwrap().as_str().to_owned();
                Expr::Assign {
                    name,
                    rhs: Box::new(self.build_expr(rhs)),
                }
            }
            Rule::comp | Rule::arith | Rule::term => {
                let mut inner: Vec<Pair<Rule>> = pair.into_inner().collect();
                if inner.len() == 1 {
                    return self.build_expr(inner.pop().unwrap());
                }
                let rhs = inner.pop().unwrap();
                let op = inner.pop().unwrap();
                let lhs = inner.pop().unwrap();
                let op = match op.as_str() {
                    "+" => BinaryExpr::Add,
                    "-" => BinaryExpr::Sub,
                    "*" => BinaryExpr::Mul,
                    "/" => BinaryExpr::Div,
                    "==" => BinaryExpr::Eq,
                    "!=" => BinaryExpr::Ne,
                    "<" => BinaryExpr::Lt,
                    "<=" => BinaryExpr::Le,
                    ">" => BinaryExpr::Gt,
                    ">=" => BinaryExpr::Ge,
                    _ => unreachable!(),
                };
                Expr::Binary(op, Box::new(self.build_expr(lhs)), Box::new(self.build_expr(rhs)))
            }
            Rule::factor => {
                let text = pair.as_str();
                let inner: Vec<Pair<Rule>> = pair.into_inner().collect();
                if inner.len() == 1 && inner[0].as_rule() == Rule::assign {
                    return self.build_expr(inner.into_iter().next().unwrap());
                }
                let trimmed = text.trim_start();
                let negative = trimmed.starts_with('-');
                let postfix = {
                    let t = text.trim_end();
                    if t.ends_with("++") {
                        Some(true)
                    } else if t.ends_with("--") {
                        Some(false)
                    } else {
                        None
                    }
                };
                let primary = inner.into_iter().next().unwrap();
                match primary.as_rule() {
                    Rule::num => {
                        let n: i32 = match primary.as_str().parse() {
                            Ok(n) => n,
                            Err(e) => parser_panic(
                                "src/parser.rs:492:67",
                                &format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
                            ),
                        };
                        if negative {
                            Expr::Literal(n.wrapping_neg())
                        } else {
                            Expr::Literal(n)
                        }
                    }
                    Rule::var_name => {
                        let name = primary.as_str().to_owned();
                        match postfix {
                            Some(true) => Expr::Inc(name),
                            Some(false) => Expr::Dec(name),
                            None => Expr::Parameter { name },
                        }
                    }
                    Rule::param_ex_span => {
                        // Only `$name` is supported here.
                        let mut name = None;
                        let text = primary.as_str();
                        if text.starts_with("${") {
                            parser_panic("src/parser.rs:508:18", "internal error: entered unreachable code");
                        }
                        for p in primary.into_inner() {
                            if p.as_rule() == Rule::var_name {
                                name = Some(p.as_str().to_owned());
                            }
                        }
                        let name = name.unwrap_or_default();
                        match postfix {
                            Some(true) => Expr::Inc(name),
                            Some(false) => Expr::Dec(name),
                            None => Expr::Parameter { name },
                        }
                    }
                    _ => unreachable!(),
                }
            }
            _ => unreachable!(),
        }
    }

    // ------------------------------------------------------------------
    // Words
    // ------------------------------------------------------------------
    fn build_word(&mut self, pair: Pair<Rule>) -> Word {
        let mut spans = Vec::new();
        for inner in pair.into_inner() {
            self.build_span(inner, &mut spans, false);
        }
        Word(spans)
    }

    fn push_literal(spans: &mut Vec<Span>, s: &str) {
        if let Some(Span::Literal(last)) = spans.last_mut() {
            last.push_str(s);
        } else {
            spans.push(Span::Literal(s.to_owned()));
        }
    }

    fn build_span(&mut self, pair: Pair<Rule>, spans: &mut Vec<Span>, quoted: bool) {
        match pair.as_rule() {
            Rule::literal_span => {
                let mut s = String::new();
                for ch in pair.into_inner() {
                    match ch.as_rule() {
                        Rule::escaped_char => {
                            s.push_str(&ch.as_str()[1..]);
                        }
                        _ => s.push_str(ch.as_str()),
                    }
                }
                spans.push(Span::Literal(s));
            }
            Rule::tilde_span => {
                let user = &pair.as_str()[1..];
                let user = if user.is_empty() {
                    None
                } else {
                    Some(user.to_owned())
                };
                spans.push(Span::Tilde(user));
            }
            Rule::any_string_span => spans.push(Span::AnyString),
            Rule::any_char_span => spans.push(Span::AnyChar),
            Rule::command_span | Rule::backtick_span => {
                let list = pair.into_inner().next().unwrap();
                let body = self.build_nested_compound_list(list);
                spans.push(Span::Command { body, quoted });
            }
            Rule::proc_subst_span => {
                let mut output = false;
                let mut body = Vec::new();
                for p in pair.into_inner() {
                    match p.as_rule() {
                        Rule::proc_subst_direction => output = p.as_str() == ">",
                        Rule::proc_subst_body => {
                            let list = p.into_inner().next().unwrap();
                            body = self.build_nested_compound_list(list);
                        }
                        _ => {}
                    }
                }
                spans.push(Span::ProcSubst { body, output });
            }
            Rule::expr_span => {
                if quoted {
                    parser_panic("src/parser.rs:781:34", "internal error: entered unreachable code");
                }
                let assign = pair.into_inner().next().unwrap();
                let expr = self.build_expr(assign);
                spans.push(Span::ArithExpr { expr });
            }
            Rule::param_ex_span => {
                self.build_param_ex_span(pair, spans, quoted);
            }
            Rule::param_span => {
                let text = pair.as_str();
                let name = text[1..].to_owned();
                spans.push(Span::Parameter {
                    name,
                    op: ExpansionOp::GetOrEmpty,
                    quoted,
                });
            }
            Rule::double_quoted_span => {
                let mut pushed = false;
                for p in pair.into_inner() {
                    match p.as_rule() {
                        Rule::literal_in_double_quoted_span => {
                            let s = unescape_double_quoted(p.as_str());
                            Self::push_literal(spans, &s);
                            pushed = true;
                        }
                        _ => {
                            self.build_span(p, spans, true);
                            pushed = true;
                        }
                    }
                }
                if !pushed {
                    spans.push(Span::Literal(String::new()));
                }
            }
            Rule::single_quoted_span => {
                let mut s = String::new();
                for p in pair.into_inner() {
                    s.push_str(p.as_str());
                }
                spans.push(Span::Literal(s));
            }
            _ => {}
        }
    }

    fn build_param_ex_span(&mut self, pair: Pair<Rule>, spans: &mut Vec<Span>, quoted: bool) {
        let text = pair.as_str();
        if !text.starts_with("${") {
            // `$name`
            spans.push(Span::Parameter {
                name: text[1..].to_owned(),
                op: ExpansionOp::GetOrEmpty,
                quoted,
            });
            return;
        }
        let length = text.starts_with("${#") && text.len() > 4;
        let mut name: Option<String> = None;
        let mut index: Option<Expr> = None;
        let mut op: Option<ExpansionOp> = None;
        let mut name_end = 2;
        for p in pair.into_inner() {
            match p.as_rule() {
                Rule::var_name => {
                    name = Some(p.as_str().to_owned());
                    name_end = p.as_span().end() - pair_start(&pair_span_start(text));
                }
                Rule::index_expr => {
                    let assign = p.into_inner().next().unwrap();
                    index = Some(self.build_expr(assign));
                }
                Rule::param_op => {
                    op = Some(self.build_param_op(p));
                }
                _ => {}
            }
        }
        let _ = name_end;
        let name = match name {
            Some(n) => n,
            None => {
                // special variable
                let rest = if length { &text[3..] } else { &text[2..] };
                rest.chars().next().unwrap().to_string()
            }
        };
        if let Some(index) = index {
            spans.push(Span::ArrayParameter { name, index, quoted });
            return;
        }
        let op = if length {
            ExpansionOp::Length
        } else {
            op.unwrap_or(ExpansionOp::GetOrEmpty)
        };
        spans.push(Span::Parameter { name, op, quoted });
    }

    fn build_param_op(&mut self, pair: Pair<Rule>) -> ExpansionOp {
        let text = pair.as_str();
        let mut word = None;
        for p in pair.clone().into_inner() {
            if p.as_rule() == Rule::word {
                word = Some(p);
            }
        }
        if text.starts_with(":-") {
            let w = word.map(|w| self.build_word(w)).unwrap_or(Word(vec![]));
            ExpansionOp::GetNullableOrDefault(w)
        } else if text.starts_with(":=") {
            let w = word.map(|w| self.build_word(w)).unwrap_or(Word(vec![]));
            ExpansionOp::GetNullableOrDefaultAndAssign(w)
        } else if text.starts_with('-') {
            let w = word.map(|w| self.build_word(w)).unwrap_or(Word(vec![]));
            ExpansionOp::GetOrDefault(w)
        } else if text.starts_with('=') {
            let w = word.map(|w| self.build_word(w)).unwrap_or(Word(vec![]));
            ExpansionOp::GetOrDefaultAndAssign(w)
        } else {
            let replace_all = text.starts_with("//");
            let (pattern, replacement) = match word {
                Some(w) => self.build_subst_word(w),
                None => (Word(vec![]), Word(vec![])),
            };
            ExpansionOp::Subst {
                pattern,
                replacement,
                replace_all,
            }
        }
    }

    /// Splits `pattern/replacement` at the first unescaped slash.
    fn build_subst_word(&mut self, pair: Pair<Rule>) -> (Word, Word) {
        let mut pattern: Vec<Span> = Vec::new();
        let mut replacement: Vec<Span> = Vec::new();
        let mut in_replacement = false;
        for inner in pair.into_inner() {
            if !in_replacement && inner.as_rule() == Rule::literal_span {
                let mut s = String::new();
                let mut rest = String::new();
                for ch in inner.into_inner() {
                    if in_replacement {
                        match ch.as_rule() {
                            Rule::escaped_char => rest.push_str(&ch.as_str()[1..]),
                            _ => rest.push_str(ch.as_str()),
                        }
                        continue;
                    }
                    match ch.as_rule() {
                        Rule::escaped_char => s.push_str(&ch.as_str()[1..]),
                        _ => {
                            if ch.as_str() == "/" {
                                in_replacement = true;
                            } else {
                                s.push_str(ch.as_str());
                            }
                        }
                    }
                }
                if !s.is_empty() {
                    pattern.push(Span::Literal(s));
                }
                if in_replacement && !rest.is_empty() {
                    replacement.push(Span::Literal(rest));
                }
            } else if in_replacement {
                self.build_span(inner, &mut replacement, false);
            } else {
                self.build_span(inner, &mut pattern, false);
            }
        }
        (Word(pattern), Word(replacement))
    }
}

fn pair_span_start(_text: &str) -> usize {
    0
}
fn pair_start(_x: &usize) -> usize {
    0
}

fn unescape_double_quoted(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek() {
                Some('"') => {
                    out.push('"');
                    chars.next();
                }
                Some('$') => {
                    out.push('$');
                    chars.next();
                }
                Some('`') => {
                    out.push('`');
                    chars.next();
                }
                _ => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}
