//! Glob-like pattern matching used by `case` and `${var/pattern/replacement}`.

#[derive(Debug, Clone)]
pub enum PatternSpan {
    /// Literal text which must match.
    Literal(String),
    /// `?`
    AnyChar,
    /// `*`
    AnyString,
    /// Literal text which is emitted (replacement only; never matched).
    Emit(String),
}

#[derive(Debug, Clone)]
pub struct Pattern {
    pub spans: Vec<PatternSpan>,
}

/// Tries to match `spans` against the beginning of `s`. Returns the number of
/// bytes consumed and the emitted text (longest match, greedy).
fn match_prefix(spans: &[PatternSpan], s: &str, out: &mut String) -> Option<usize> {
    match spans.first() {
        None => Some(0),
        Some(PatternSpan::Emit(text)) => {
            let mut rest_out = String::new();
            let consumed = match_prefix(&spans[1..], s, &mut rest_out)?;
            out.push_str(text);
            out.push_str(&rest_out);
            Some(consumed)
        }
        Some(PatternSpan::Literal(lit)) => {
            if s.starts_with(lit.as_str()) {
                let mut rest_out = String::new();
                let consumed = match_prefix(&spans[1..], &s[lit.len()..], &mut rest_out)?;
                out.push_str(&rest_out);
                Some(lit.len() + consumed)
            } else {
                None
            }
        }
        Some(PatternSpan::AnyChar) => {
            let ch = s.chars().next()?;
            let len = ch.len_utf8();
            let mut rest_out = String::new();
            let consumed = match_prefix(&spans[1..], &s[len..], &mut rest_out)?;
            out.push_str(&rest_out);
            Some(len + consumed)
        }
        Some(PatternSpan::AnyString) => {
            // Greedy: try the longest first.
            let mut positions: Vec<usize> = s.char_indices().map(|(i, _)| i).collect();
            positions.push(s.len());
            for &pos in positions.iter().rev() {
                let mut rest_out = String::new();
                if let Some(consumed) = match_prefix(&spans[1..], &s[pos..], &mut rest_out) {
                    out.push_str(&rest_out);
                    return Some(pos + consumed);
                }
            }
            None
        }
    }
}

impl Pattern {
    /// Finds the leftmost match in `s`. Returns `(start, end)`.
    pub fn find(&self, s: &str) -> Option<(usize, usize)> {
        for (start, _) in s.char_indices() {
            let mut out = String::new();
            if let Some(consumed) = match_prefix(&self.spans, &s[start..], &mut out) {
                return Some((start, start + consumed));
            }
        }
        None
    }

    pub fn matches(&self, s: &str) -> bool {
        self.find(s).is_some()
    }

    /// Applies a replacement pattern against the beginning of `rest`.
    /// Returns `(emitted, consumed)`.
    pub fn render_replacement(&self, rest: &str) -> Option<(String, usize)> {
        let mut out = String::new();
        let consumed = match_prefix(&self.spans, rest, &mut out)?;
        Some((out, consumed))
    }

    pub fn replace(&self, value: &str, replacement: &Pattern, replace_all: bool) -> String {
        let mut result = String::new();
        let mut rest = value;
        loop {
            let (start, end) = match self.find(rest) {
                Some(m) => m,
                None => {
                    result.push_str(rest);
                    break;
                }
            };
            // An empty match consumes one character.
            let mut end = end;
            if end == start {
                match rest[start..].chars().next() {
                    Some(c) => end = start + c.len_utf8(),
                    None => {
                        result.push_str(rest);
                        break;
                    }
                }
            }
            result.push_str(&rest[..start]);
            let after = &rest[end..];
            match replacement.render_replacement(after) {
                Some((emitted, consumed)) => {
                    result.push_str(&emitted);
                    rest = &after[consumed..];
                    if !replace_all {
                        result.push_str(rest);
                        break;
                    }
                }
                None => {
                    // The replacement failed: keep the matched text and continue.
                    result.push_str(&rest[start..end]);
                    rest = after;
                }
            }
            if rest.is_empty() {
                break;
            }
        }
        result
    }
}
EOF
