pub enum ClapError {
    /// Help or version was requested. The text should be printed.
    Info(String),
    /// A usage error. The text should be printed.
    Error(String),
}

fn colored(stderr_tty: bool, code: &str, text: &str) -> String {
    if stderr_tty {
        format!("\x1b[{}m{}\x1b[0m", code, text)
    } else {
        text.to_owned()
    }
}

pub fn error_prefix() -> String {
    let tty = std::io::stderr().is_terminal();
    colored(tty, "1;31", "error:")
}

fn try_help() -> String {
    let tty = std::io::stderr().is_terminal();
    format!("For more information try {}", colored(tty, "32", "--help"))
}

fn yellow(text: &str) -> String {
    let tty = std::io::stderr().is_terminal();
    colored(tty, "33", text)
}

fn red_bold(text: &str) -> String {
    let tty = std::io::stderr().is_terminal();
    colored(tty, "1;31", text)
}

/// Formats "smart" usage: the app name followed by used args.
