    if used.is_empty() {
        return format!("{} {}", app.name, app.usage).trim_end().to_owned();
    }
    format!("{} {}", app.name, used.join(" "))
}

pub fn unexpected_argument(app: &App, arg: &str, used: &[String]) -> ClapError {
    let mut msg = format!(
        "{} Found argument '{}' which wasn't expected, or isn't valid in this context\n",
        error_prefix(),
        yellow(arg)
    );
    // "Did you mean" suggestion for long flags.
    if let Some(stripped) = arg.strip_prefix("--") {
        let mut candidates: Vec<&str> = app.flags.iter().filter_map(|f| f.long).collect();
        candidates.extend(app.opts.iter().filter_map(|o| o.long));
        candidates.push("help");
        if let Some(best) = candidates
            .iter()
            .filter(|c| similar(stripped, c))
            .max_by_key(|c| c.len())
