fn similar(a: &str, b: &str) -> bool {
    // Jaro-Winkler-ish approximation: accept if `a` is a prefix of `b` or
    // they share most characters.
    if b.starts_with(a) && !a.is_empty() {
        return true;
    }
    let dist = strsim_jaro(a, b);
    dist > 0.8
}

fn strsim_jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let match_distance = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_matches = vec![false; a.len()];
    let mut b_matches = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = i.saturating_sub(match_distance);
        let end = (i + match_distance + 1).min(b.len());
        for j in start..end {
            if b_matches[j] || a[i] != b[j] {
                continue;
            }
            a_matches[i] = true;
            b_matches[j] = true;
            matches += 1;
            break;
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if !a_matches[i] {
            continue;
        }
        while !b_matches[k] {
            k += 1;
        }
        if a[i] != b[k] {
            t += 1;
        }
        k += 1;
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (t / 2) as f64) / m) / 3.0
}

pub fn parse(app: &App, args: &[String]) -> Result<Matches, ClapError> {
    let mut matches = Matches::default();
    let mut used: Vec<String> = Vec::new();
    let mut pos_index = 0;
    let mut i = 0;
    let mut seen_flags: Vec<&'static str> = Vec::new();
    while i < args.len() {
        let arg = &args[i];
        if arg == "--help" || arg == "-h" {
            return Err(ClapError::Info(app.help.to_owned()));
        }
        if arg == "--version" || arg == "-V" {
            return Err(ClapError::Info(format!("{} {}\n", app.name, app.version)));
        }
        if let Some(long) = arg.strip_prefix("--") {
            let (long_name, inline_value) = match long.find('=') {
                Some(idx) => (&long[..idx], Some(long[idx + 1..].to_owned())),
                None => (long, None),
            };
            if let Some(flag) = app.flags.iter().find(|f| f.long == Some(long_name)) {
                if seen_flags.contains(&flag.name) {
                    return Err(multiple_occurrences(app, &format!("--{}", long_name), &used));
                }
                seen_flags.push(flag.name);
                used.push(format!("--{}", long_name));
                matches.flags.push(flag.name);
                i += 1;
                continue;
            }
            if let Some(opt) = app.opts.iter().find(|o| o.long == Some(long_name)) {
                let value = match inline_value {
                    Some(v) => v,
                    None => {
                        i += 1;
                        match args.get(i) {
                            Some(v) => v.clone(),
                            None => return Err(missing_value(app, opt, &used)),
                        }
                    }
                };
                used.push(format!("--{} <{}>", long_name, opt.value_name));
                matches.opts.push((opt.name, value));
                i += 1;
                continue;
            }
            return Err(unexpected_argument(app, arg, &used));
        }
        if arg.len() > 1 && arg.starts_with('-') && !arg.starts_with("--") {
            // Short flags, possibly clustered.
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                if c == 'h' {
                    return Err(ClapError::Info(app.help.to_owned()));
                }
                if c == 'V' {
                    return Err(ClapError::Info(format!("{} {}\n", app.name, app.version)));
                }
                if let Some(flag) = app.flags.iter().find(|f| f.short == Some(c)) {
                    if seen_flags.contains(&flag.name) {
                        return Err(multiple_occurrences(app, &format!("-{}", c), &used));
                    }
                    seen_flags.push(flag.name);
                    used.push(format!("-{}", c));
                    matches.flags.push(flag.name);
                    j += 1;
                    continue;
                }
                if let Some(opt) = app.opts.iter().find(|o| o.short == Some(c)) {
                    let rest: String = chars[j + 1..].iter().collect();
                    let value = if !rest.is_empty() {
                        rest.strip_prefix('=').unwrap_or(&rest).to_owned()
                    } else {
                        i += 1;
                        match args.get(i) {
                            Some(v) => v.clone(),
                            None => {
                                used.push(format!("-{} <{}>", c, opt.value_name));
                                return Err(missing_value_with_used(app, opt, &used, &matches));
                            }
                        }
                    };
                    if matches.opts.iter().any(|(n, _)| *n == opt.name) {
                        return Err(multiple_occurrences(app, &format!("-{} <{}>", c, opt.value_name), &used));
                    }
                    used.push(format!("-{} <{}>", c, opt.value_name));
                    matches.opts.push((opt.name, value));
                    j = chars.len();
                    continue;
                }
                return Err(unexpected_argument(app, &format!("-{}", c), &used));
            }
            i += 1;
            continue;
        }
        // Positional
        if pos_index < app.positionals.len() {
            let spec = &app.positionals[pos_index];
            matches.positionals.push((spec.name, arg.clone()));
            pos_index += 1;
            i += 1;
            continue;
        }
        return Err(unexpected_argument(app, arg, &used));
    }
    // Check required positionals.
    let missing: Vec<&PosSpec> = app
        .positionals
        .iter()
        .filter(|p| p.required && !matches.positionals.iter().any(|(n, _)| *n == p.name))
        .collect();
    if !missing.is_empty() {
        let mut msg = format!(
            "{} The following required arguments were not provided:\n",
            error_prefix()
        );
        for m in &missing {
            msg.push_str(&format!("    {}\n", red_bold(&format!("<{}>", m.name))));
        }
        let mut usage_parts: Vec<String> = missing.iter().map(|m| format!("<{}>", m.name)).collect();
        usage_parts.extend(used.iter().cloned());
        let usage = if used.is_empty() {
            format!("{} {}", app.name, app.usage)
        } else {
            format!("{} {}", app.name, usage_parts.join(" "))
        };
        msg.push_str(&format!("\nUSAGE:\n    {}\n\n{}\n", usage, try_help()));
        return Err(ClapError::Error(msg));
    }
    Ok(matches)
}

fn missing_value(app: &App, opt: &OptSpec, used: &[String]) -> ClapError {
    let arg_name = match (opt.short, opt.long) {
        (Some(s), _) => format!("-{} <{}>", s, opt.value_name),
        (None, Some(l)) => format!("--{} <{}>", l, opt.value_name),
        _ => opt.name.to_owned(),
    };
    let mut all_used = used.to_vec();
    all_used.push(arg_name.clone());
    ClapError::Error(format!(
        "{} The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\n{}\n",
        error_prefix(),
        yellow(&arg_name),
        smart_usage(app, &all_used),
        try_help()
    ))
}

fn missing_value_with_used(app: &App, opt: &OptSpec, used: &[String], matches: &Matches) -> ClapError {
    // clap 2 reports missing required positionals before the missing value
    // when positionals are required.
    let missing: Vec<&PosSpec> = app
        .positionals
        .iter()
        .filter(|p| p.required && !matches.positionals.iter().any(|(n, _)| *n == p.name))
        .collect();
    if !missing.is_empty() {
        let mut msg = format!(
            "{} The following required arguments were not provided:\n",
            error_prefix()
        );
        for m in &missing {
            msg.push_str(&format!("    {}\n", red_bold(&format!("<{}>", m.name))));
        }
        let mut usage_parts: Vec<String> = missing.iter().map(|m| format!("<{}>", m.name)).collect();
        usage_parts.extend(used.iter().cloned());
        let usage = format!("{} {}", app.name, usage_parts.join(" "));
        msg.push_str(&format!("\nUSAGE:\n    {}\n\n{}\n", usage, try_help()));
        return ClapError::Error(msg);
    }
    let arg_name = match (opt.short, opt.long) {
        (Some(s), _) => format!("-{} <{}>", s, opt.value_name),
        (None, Some(l)) => format!("--{} <{}>", l, opt.value_name),
        _ => opt.name.to_owned(),
    };
    ClapError::Error(format!(
        "{} The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\n{}\n",
        error_prefix(),
        yellow(&arg_name),
        smart_usage(app, used),
        try_help()
    ))
}

fn multiple_occurrences(app: &App, arg: &str, used: &[String]) -> ClapError {
    ClapError::Error(format!(
        "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\n{}\n",
        error_prefix(),
        yellow(arg),
        smart_usage(app, used),
        try_help()
    ))
}

pub fn invalid_value(arg: &str, err: &str) -> ClapError {
    ClapError::Error(format!(
        "{} Invalid value for '{}': {}\n",
        error_prefix(),
        yellow(arg),
        err
    ))
}
EOF
echo ok"}

