#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ProcessState {
    Running,
    Stopped(Pid),
    Completed(i32),
}

#[derive(Debug, Clone)]
pub struct Job {
    pub id: usize,
    pub pgid: Pid,
    pub cmd: String,
    pub processes: Vec<Pid>,
    pub states: Vec<ProcessState>,
}

impl Job {
    pub fn is_completed(&self) -> bool {
        self.states
            .iter()
            .all(|s| matches!(s, ProcessState::Completed(_)))
    }

    pub fn is_stopped(&self) -> bool {
        self.states
            .iter()
            .all(|s| !matches!(s, ProcessState::Running))
            && self.states.iter().any(|s| matches!(s, ProcessState::Stopped(_)))
    }

    pub fn last_status(&self) -> i32 {
        match self.states.last() {
            Some(ProcessState::Completed(status)) => *status,
            _ => 0,
        }
    }
}

/// Restores the default signal dispositions in a child process.
pub fn restore_signals() {
    unsafe {
        for sig in [
            Signal::SIGINT,
            Signal::SIGQUIT,
            Signal::SIGTSTP,
            Signal::SIGTTIN,
            Signal::SIGTTOU,
            Signal::SIGCHLD,
            Signal::SIGPIPE,
        ] {
            let _ = signal::signal(sig, SigHandler::SigDfl);
        }
    }
}

pub fn ignore_shell_signals() {
    unsafe {
        for sig in [
            Signal::SIGINT,
            Signal::SIGQUIT,
            Signal::SIGTSTP,
            Signal::SIGTTIN,
            Signal::SIGTTOU,
        ] {
            let _ = signal::signal(sig, SigHandler::SigIgn);
        }
    }
}

pub fn fork() -> Option<ForkResult> {
    match unsafe { unistd::fork() } {
        Ok(r) => Some(r),
        Err(_) => None,
    }
}

pub fn pipe() -> (RawFd, RawFd) {
    use std::os::unix::io::IntoRawFd;
    let (r, w) = unistd::pipe().expect("failed to pipe");
    (r.into_raw_fd(), w.into_raw_fd())
}

pub fn dup2(from: RawFd, to: RawFd) -> bool {
    unistd::dup2(from, to).is_ok()
}

pub fn close(fd: RawFd) {
    let _ = unistd::close(fd);
}

pub fn getpid() -> Pid {
    unistd::getpid()
}

/// Execs the program. Only returns on error.
pub fn execv(path: &str, argv: &[String], env: &[String]) -> nix::Error {
    let c_path = CString::new(path).unwrap_or_else(|_| CString::new("").unwrap());
    let c_argv: Vec<CString> = argv
        .iter()
        .map(|a| CString::new(a.as_bytes()).unwrap_or_else(|_| CString::new("").unwrap()))
        .collect();
    let c_env: Vec<CString> = env
        .iter()
        .map(|a| CString::new(a.as_bytes()).unwrap_or_else(|_| CString::new("").unwrap()))
        .collect();
    match unistd::execve(&c_path, &c_argv, &c_env) {
        Ok(_) => unreachable!(),
        Err(e) => e,
    }
}

pub fn execvp(file: &str, argv: &[String]) -> nix::Error {
    let c_file = CString::new(file).unwrap_or_else(|_| CString::new("").unwrap());
    let c_argv: Vec<CString> = argv
        .iter()
        .map(|a| CString::new(a.as_bytes()).unwrap_or_else(|_| CString::new("").unwrap()))
        .collect();
    match unistd::execvp(&c_file, &c_argv) {
        Ok(_) => unreachable!(),
        Err(e) => e,
    }
}

pub enum Waited {
    Exited(Pid, i32),
    Signaled(Pid),
    Stopped(Pid),
    NoChild,
    Other,
}

/// Waits for any child process.
pub fn wait_any(nohang: bool) -> Waited {
    let mut flags = WaitPidFlag::WUNTRACED;
    if nohang {
        flags |= WaitPidFlag::WNOHANG;
    }
    match waitpid(None, Some(flags)) {
        Ok(WaitStatus::Exited(pid, status)) => Waited::Exited(pid, status),
        Ok(WaitStatus::Signaled(pid, _, _)) => Waited::Signaled(pid),
        Ok(WaitStatus::Stopped(pid, _)) => Waited::Stopped(pid),
        Ok(WaitStatus::StillAlive) => Waited::Other,
        Ok(_) => Waited::Other,
        Err(nix::Error::ECHILD) => Waited::NoChild,
        Err(nix::Error::EINTR) => Waited::Other,
        Err(_) => Waited::NoChild,
    }
}

pub fn wait_pid(pid: Pid) -> Waited {
    match waitpid(pid, Some(WaitPidFlag::WUNTRACED)) {
        Ok(WaitStatus::Exited(pid, status)) => Waited::Exited(pid, status),
        Ok(WaitStatus::Signaled(pid, _, _)) => Waited::Signaled(pid),
        Ok(WaitStatus::Stopped(pid, _)) => Waited::Stopped(pid),
        Ok(_) => Waited::Other,
        Err(nix::Error::ECHILD) => Waited::NoChild,
        Err(_) => Waited::Other,
    }
}

pub fn kill_cont(pgid: Pid) {
    let _ = signal::killpg(pgid, Signal::SIGCONT);
}

pub fn set_terminal_pgid(fd: RawFd, pgid: Pid) {
    unsafe {
        libc::tcsetpgrp(fd, pgid.as_raw());
    }
}
