fn write_fd(fd: RawFd, data: &[u8]) -> bool {
    let mut written = 0;
    while written < data.len() {
        match nix::unistd::write(unsafe { std::os::fd::BorrowedFd::borrow_raw(fd) }, &data[written..]) {
            Ok(n) => written += n,
            Err(nix::Error::EINTR) => continue,
            Err(e) => {
                if e == nix::Error::ENOSPC {
                    crate::panic_at("src/utils.rs:51:47", "failed to write: ENOSPC");
                }
                return false;
            }
        }
    }
