            history_hook: None,
        };
        shell.rebuild_path_table();
        shell
    }

    pub fn rebuild_path_table(&mut self) {
        let path = self.get_str("PATH");
        self.path_table.clear();
        for dir in path.split(':') {
            if dir.is_empty() {
                continue;
            }
            if let Ok(entries) = std::fs::read_dir(dir) {
                for entry in entries.flatten() {
                    let name = entry.file_name().to_string_lossy().into_owned();
                    let full = format!("{}/{}", dir, name);
                    self.path_table.entry(name).or_insert(full);
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // Variables
    // ------------------------------------------------------------------
    pub fn get_var(&self, name: &str) -> Option<&Variable> {
        if let Some(frame) = self.frames.last() {
            if let Some(v) = frame.vars.get(name) {
                return Some(v);
            }
        }
        self.vars.get(name)
    }

    pub fn get_str(&self, name: &str) -> String {
        self.get_var(name).map(|v| v.as_str().to_owned()).unwrap_or_default()
    }

    /// Sets a variable: a local one if it exists in the current frame,
    /// otherwise a global one.
    pub fn set_value(&mut self, name: &str, value: Value) {
        if let Some(frame) = self.frames.last_mut() {
            if let Some(v) = frame.vars.get_mut(name) {
                v.value = value;
                return;
            }
        }
        let exported = self.vars.get(name).map(|v| v.exported).unwrap_or(false);
        if exported {
            if let Value::String(ref s) = value {
                std::env::set_var(name, s);
            }
        }
        self.vars.insert(
            name.to_owned(),
            Variable {
                value,
                exported,
            },
        );
    }

    pub fn set_str(&mut self, name: &str, value: &str) {
        self.set_value(name, Value::String(value.to_owned()));
    }

    pub fn set_global_str(&mut self, name: &str, value: &str) {
        let exported = self.vars.get(name).map(|v| v.exported).unwrap_or(false);
        if exported {
            std::env::set_var(name, value);
        }
        self.vars.insert(
            name.to_owned(),
            Variable {
                value: Value::String(value.to_owned()),
                exported,
            },
        );
    }

    pub fn set_local(&mut self, name: &str, value: Value) -> bool {
        if let Some(frame) = self.frames.last_mut() {
            frame.vars.insert(name.to_owned(), Variable::new(value));
            true
        } else {
            false
        }
    }

    pub fn export(&mut self, name: &str) {
        let value = self.get_str(name);
        std::env::set_var(name, &value);
        if let Some(v) = self.vars.get_mut(name) {
            v.exported = true;
        } else {
            self.vars.insert(
                name.to_owned(),
                Variable {
                    value: Value::String(value),
                    exported: true,
                },
            );
        }
    }

    pub fn unset(&mut self, name: &str) {
        if let Some(frame) = self.frames.last_mut() {
            frame.vars.remove(name);
        }
        if let Some(v) = self.vars.remove(name) {
            if v.exported {
                std::env::remove_var(name);
            }
        }
    }

    pub fn args(&self) -> &[String] {
        match self.frames.last() {
            Some(frame) => &frame.args,
            None => &[],
        }
    }

    pub fn current_dir(&self) -> PathBuf {
        match std::env::current_dir() {
            Ok(p) => p,
            Err(e) => crate::panic_at(
                "src/builtins/cd.rs:8:43",
                &format!("failed to getcwd(): {:?}", e),
            ),
        }
    }

    // ------------------------------------------------------------------
    // Execution
    // ------------------------------------------------------------------
    pub fn run_script(&mut self, script: &str, ctx: &Context) -> ExitStatus {
        match parser::parse(script) {
            Ok(ast) => self.run_ast(&ast, ctx),
            Err(err) => {
                print_err(&format!("nsh: parse error: {}", err));
                self.last_status = -1;
                ExitStatus::ExitedWith(-1)
            }
        }
    }

    pub fn run_ast(&mut self, ast: &Ast, ctx: &Context) -> ExitStatus {
        self.run_terms(&ast.terms, ctx)
    }

    pub fn run_terms(&mut self, terms: &[Term], ctx: &Context) -> ExitStatus {
        let mut last = ExitStatus::ExitedWith(0);
        for term in terms {
            for pipeline in &term.pipelines {
                let should_run = match pipeline.run_if {
                    RunIf::Always => true,
                    RunIf::Success => self.last_status == 0,
                    // The original implementation runs the `||` side
                    // unconditionally.
                    RunIf::Failure => true,
                };
                if !should_run {
                    continue;
                }
                let mut ctx2 = *ctx;
                ctx2.background = term.background;
                last = self.run_pipeline(pipeline, &ctx2, &term.code);
                match last {
                    ExitStatus::ExitedWith(status) => {
                        self.last_status = status;
                        if self.errexit && status != 0 {
                            self.exit(status);
                        }
                    }
                    ExitStatus::Break | ExitStatus::Continue | ExitStatus::Return => {
                        return last;
                    }
                    ExitStatus::Running(_) => {}
                }
                if let Some(code) = self.exiting {
                    self.exit(code);
                }
            }
        }
        last
    }

    pub fn exit(&mut self, status: i32) -> ! {
        use std::io::Write;
        let _ = std::io::stdout().flush();
        std::process::exit(status);
    }

    fn run_pipeline(&mut self, pipeline: &Pipeline, ctx: &Context, code: &str) -> ExitStatus {
        let mut last_status = ExitStatus::ExitedWith(0);
        let mut pids: Vec<Pid> = Vec::new();
        let mut pgid: Option<Pid> = ctx.pgid;
        let mut stdin = ctx.stdin;
        let n = pipeline.commands.len();
        for (i, command) in pipeline.commands.iter().enumerate() {
            let is_last = i + 1 == n;
            let (stdout, pipe_w, pipe_r) = if is_last {
                (ctx.stdout, None, None)
            } else {
                let (r, w) = process::pipe();
                (w, Some(w), Some(r))
            };
            let cmd_ctx = Context {
                stdin,
                stdout,
                stderr: ctx.stderr,
                pgid,
                background: ctx.background,
                interactive: ctx.interactive,
            };
            let result = self.run_command(command, &cmd_ctx);
            if let ExitStatus::Running(pid) = result {
                if pgid.is_none() {
                    pgid = Some(pid);
                }
                pids.push(pid);
            }
            last_status = result;
            if let Some(w) = pipe_w {
                process::close(w);
            }
            // NOTE: the read end is intentionally not closed in the parent
            // (mirrors the original implementation).
            if let Some(r) = pipe_r {
                stdin = r;
            }
            match result {
                ExitStatus::Break | ExitStatus::Continue | ExitStatus::Return => {
                    if pids.is_empty() {
                        return result;
                    }
                }
                _ => {}
            }
        }

        if pids.is_empty() {
            return last_status;
        }

        // Create a job for the external processes.
        let job_id = self.alloc_job_id();
        let job = Job {
            id: job_id,
            pgid: pgid.unwrap(),
            cmd: code.to_owned(),
            processes: pids.clone(),
            states: vec![ProcessState::Running; pids.len()],
        };
        self.jobs.push(job);
        let is_external_last = matches!(last_status, ExitStatus::Running(_));

        if ctx.background && self.interactive {
            self.last_back_pid = pids.last().unwrap().as_raw();
            return ExitStatus::ExitedWith(0);
        }

        if ctx.background {
            self.last_back_pid = pids.last().unwrap().as_raw();
        }

        let status = self.wait_for_job(job_id, ctx);
        if ctx.background {
            // Report the completion of the "background" job immediately.
            self.check_jobs();
            return ExitStatus::ExitedWith(status);
        }
        if is_external_last {
            ExitStatus::ExitedWith(status)
        } else {
            match last_status {
                ExitStatus::Running(_) => ExitStatus::ExitedWith(status),
                other => other,
            }
        }
    }

    fn alloc_job_id(&self) -> usize {
        let mut id = 1;
        while self.jobs.iter().any(|j| j.id == id) {
            id += 1;
        }
        id
    }

    pub fn find_job_mut(&mut self, pid: Pid) -> Option<(&mut Job, usize)> {
        for job in self.jobs.iter_mut() {
            if let Some(idx) = job.processes.iter().position(|p| *p == pid) {
                return Some((job, idx));
            }
        }
        None
    }

    /// Waits until the job is completed or stopped. Returns its exit status.
    pub fn wait_for_job(&mut self, job_id: usize, ctx: &Context) -> i32 {
        if self.interactive {
            if let Some(job) = self.jobs.iter().find(|j| j.id == job_id) {
                process::set_terminal_pgid(0, job.pgid);
            }
        }
        loop {
            let done = match self.jobs.iter().find(|j| j.id == job_id) {
                Some(job) => job.is_completed() || job.is_stopped(),
                None => true,
            };
            if done {
                break;
            }
            match process::wait_any(false) {
                Waited::Exited(pid, status) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(status);
                    }
                }
                Waited::Signaled(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(-1);
                    }
                }
                Waited::Stopped(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Stopped(pid);
                    }
                }
                Waited::NoChild => break,
                Waited::Other => {}
            }
        }
        if self.interactive {
            process::set_terminal_pgid(0, self.shell_pgid);
        }
        let _ = ctx;
        let (status, completed, stopped, cmd) = match self.jobs.iter().find(|j| j.id == job_id) {
            Some(job) => (job.last_status(), job.is_completed(), job.is_stopped(), job.cmd.clone()),
            None => (0, true, false, String::new()),
        };
        if stopped {
            print_err(&format!("nsh: [{}] Stopped: {}", job_id, cmd));
            self.last_fore_job = Some(job_id);
            return 0;
        }
        if completed && !ctx.background {
            self.jobs.retain(|j| j.id != job_id);
        }
        status
    }

    /// Reaps finished background jobs and reports them.
    pub fn check_jobs(&mut self) {
        loop {
            match process::wait_any(true) {
                Waited::Exited(pid, status) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(status);
                    }
                }
                Waited::Signaled(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(-1);
                    }
                }
                Waited::Stopped(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Stopped(pid);
                    }
                }
                _ => break,
            }
        }
        let completed: Vec<Job> = self.jobs.iter().filter(|j| j.is_completed()).cloned().collect();
        for job in completed {
            println!("[{}] Done: {}", job.id, job.cmd);
            self.jobs.retain(|j| j.id != job.id);
        }
        let _ = std::io::Write::flush(&mut std::io::stdout());
    }

    pub fn run_command(&mut self, command: &Command, ctx: &Context) -> ExitStatus {
        if let Some(code) = self.exiting {
            self.exit(code);
        }
        match command {
            Command::SimpleCommand {
                argv,
                redirects,
                assignments,
            } => self.run_simple_command(argv, redirects, assignments, ctx),
            Command::Assignment { assignments } => {
                for assignment in assignments {
                    let value = self.evaluate_initializer(&assignment.initializer, ctx);
                    self.set_value(&assignment.name, value);
                }
                ExitStatus::ExitedWith(0)
            }
            Command::If {
                condition,
                then_part,
                elif_parts,
                else_part,
            } => {
                let cond = self.run_terms(condition, ctx);
                if let ExitStatus::ExitedWith(0) = cond {
                    return self.run_terms(then_part, ctx);
                }
                if !matches!(cond, ExitStatus::ExitedWith(_)) {
                    return cond;
                }
                for elif in elif_parts {
                    let cond = self.run_terms(&elif.condition, ctx);
                    if let ExitStatus::ExitedWith(0) = cond {
                        // The original implementation runs the main then-part.
                        return self.run_terms(then_part, ctx);
                    }
                    if !matches!(cond, ExitStatus::ExitedWith(_)) {
                        return cond;
                    }
                }
                if let Some(else_part) = else_part {
                    return self.run_terms(else_part, ctx);
                }
                ExitStatus::ExitedWith(0)
            }
            Command::While { condition, body } => {
                let mut last = ExitStatus::ExitedWith(0);
                loop {
                    let cond = self.run_terms(condition, ctx);
                    match cond {
                        ExitStatus::ExitedWith(0) => {}
                        ExitStatus::ExitedWith(_) => break,
                        other => return other,
                    }
                    last = self.run_terms(body, ctx);
                }
                last
            }
            Command::For {
                var_name,
                words,
                body,
            } => {
                let values = match self.expand_words(words, ctx) {
                    Ok(v) => v,
                    Err(_) => return ExitStatus::ExitedWith(1),
                };
                for value in values {
                    self.set_str(var_name, &value);
                    match self.run_terms(body, ctx) {
                        ExitStatus::Break => break,
                        ExitStatus::Continue => continue,
                        ExitStatus::Return => return ExitStatus::Return,
                        _ => {}
                    }
                }
                ExitStatus::ExitedWith(0)
            }
            Command::ArithFor {
                init,
                cond,
                update,
                body,
            } => {
                self.evaluate_expr(init);
                loop {
                    if self.evaluate_expr(cond) != 1 {
                        break;
                    }
                    match self.run_terms(body, ctx) {
                        ExitStatus::Break => break,
                        ExitStatus::Continue => {}
                        ExitStatus::Return => return ExitStatus::Return,
                        _ => {}
                    }
                    self.evaluate_expr(update);
                }
                ExitStatus::ExitedWith(0)
            }
            Command::Case { word, cases } => {
                let value = match self.expand_word_into_string(word, ctx) {
                    Ok(v) => v,
                    Err(_) => return ExitStatus::ExitedWith(1),
                };
                for case in cases {
                    for pattern_word in &case.patterns {
                        let pattern = self.word_to_pattern(pattern_word, ctx, false);
                        if pattern.matches(&value) {
                            return self.run_terms(&case.body, ctx);
                        }
                    }
                }
                ExitStatus::ExitedWith(0)
            }
            Command::FunctionDef { name, body } => {
                self.functions.insert(name.clone(), (**body).clone());
                ExitStatus::ExitedWith(0)
            }
            Command::LocalDef { declarations } => {
                if self.frames.is_empty() {
                    print_err("nsh: local variable can only be used in a function");
                    return ExitStatus::ExitedWith(1);
                }
                for decl in declarations {
                    match decl {
                        LocalDeclaration::Assignment(assignment) => {
                            let value = self.evaluate_initializer(&assignment.initializer, ctx);
                            self.set_local(&assignment.name, value);
                        }
                        LocalDeclaration::Name(name) => {
                            self.set_local(name, Value::String(String::new()));
                        }
                    }
                }
                ExitStatus::ExitedWith(0)
            }
            Command::Group { terms } => self.run_terms(terms, ctx),
            Command::SubShellGroup { terms } => {
                match process::fork() {
                    Some(ForkResult::Child) => {
                        let status = self.run_terms(terms, ctx);
                        let code = match status {
                            ExitStatus::ExitedWith(c) => c,
                            _ => 0,
                        };
                        self.exit(code);
                    }
                    Some(ForkResult::Parent { child }) => {
                        let status = match process::wait_pid(child) {
                            Waited::Exited(_, s) => s,
                            Waited::Signaled(_) => -1,
                            _ => 0,
                        };
                        ExitStatus::ExitedWith(status)
                    }
                    None => ExitStatus::ExitedWith(1),
                }
            }
            Command::Return { .. } => ExitStatus::Return,
            Command::Break => ExitStatus::Break,
            Command::Continue => ExitStatus::Continue,
        }
    }

    fn evaluate_initializer(&mut self, initializer: &Initializer, ctx: &Context) -> Value {
        match initializer {
            Initializer::String(word) => {
                let s = self.expand_word_into_string(word, ctx).unwrap_or_default();
                Value::String(s)
            }
            Initializer::Array(words) => {
                let elems = self.expand_words(words, ctx).unwrap_or_default();
                Value::Array(elems)
            }
        }
    }

    fn run_simple_command(
        &mut self,
        argv: &[Word],
        redirects: &[parser::Redirection],
        assignments: &[Assignment],
        ctx: &Context,
    ) -> ExitStatus {
        let mut args = match self.expand_words(argv, ctx) {
            Ok(a) => a,
            Err(ExpandError::NoMatches) => {
                print_err("nsh: error: no matches");
                return ExitStatus::ExitedWith(1);
            }
        };
        if args.is_empty() {
            return ExitStatus::ExitedWith(0);
        }

        // Alias expansion.
        if let Some(body) = self.aliases.iter().find(|(n, _)| *n == args[0]).map(|(_, b)| b.clone()) {
            let mut new_args: Vec<String> = body.trim().split(' ').map(|s| s.to_owned()).collect();
            new_args.extend(args.drain(1..));
            args = new_args;
        }

        // Temporary assignments (for external commands).
        let mut env_assignments: Vec<(String, String)> = Vec::new();
        for assignment in assignments {
            let value = self.evaluate_initializer(&assignment.initializer, ctx);
            let s = match value {
                Value::String(s) => s,
                Value::Array(a) => a.first().cloned().unwrap_or_default(),
            };
            env_assignments.push((assignment.name.clone(), s));
        }

        // Functions.
        if let Some(body) = self.functions.get(&args[0]).cloned() {
            return self.call_function(&body, &args[1..], ctx);
        }

        // Builtins.
        if crate::builtins::is_builtin(&args[0]) {
            let fds = match self.open_redirects(redirects, ctx, false) {
                Some(fds) => fds,
                None => return ExitStatus::ExitedWith(1),
            };
            let mut bctx = *ctx;
            for (fd, target) in &fds {
                match *fd {
                    0 => bctx.stdin = *target,
                    1 => bctx.stdout = *target,
                    2 => bctx.stderr = *target,
                    _ => {}
                }
            }
            let status = crate::builtins::run_builtin(self, &args, &bctx);
            for (_, target) in fds {
                if target != ctx.stdin && target != ctx.stdout && target != ctx.stderr {
                    process::close(target);
                }
            }
            return status;
        }

        // External commands.
        let path = match self.resolve_path(&args[0]) {
            Some(p) => p,
            None => {
                print_err(&format!("nsh: command not found `{}'", args[0]));
                return ExitStatus::ExitedWith(1);
            }
        };

        let fds = match self.open_redirects(redirects, ctx, true) {
            Some(fds) => fds,
            None => return ExitStatus::ExitedWith(1),
        };

        let mut env: Vec<String> = std::env::vars().map(|(k, v)| format!("{}={}", k, v)).collect();
        for (k, v) in &env_assignments {
            env.retain(|e| !e.starts_with(&format!("{}=", k)));
            env.push(format!("{}={}", k, v));
        }

        use std::io::Write;
        let _ = std::io::stdout().flush();
        match process::fork() {
            Some(ForkResult::Child) => {
                let pid = process::getpid();
                if self.interactive {
                    let pgid = ctx.pgid.unwrap_or(pid);
                    let _ = nix::unistd::setpgid(pid, pgid);
                    if !ctx.background {
                        process::set_terminal_pgid(0, pgid);
                    }
                }
                process::restore_signals();
                if ctx.stdin != 0 {
                    process::dup2(ctx.stdin, 0);
                }
                if ctx.stdout != 1 {
                    process::dup2(ctx.stdout, 1);
                }
                if ctx.stderr != 2 {
                    process::dup2(ctx.stderr, 2);
                }
                for (fd, target) in &fds {
                    process::dup2(*target, *fd);
                }
                let err = process::execv(&path, &args, &env);
                let msg = match err {
                    nix::Error::EACCES => {
                        format!("nsh: Failed to exec \"{}\" (EACCESS). chmod(1) may help.", path)
                    }
                    e => format!("nsh: Failed to exec \"{}\" ({})", path, e),
                };
                print_err(&msg);
                std::process::exit(1);
            }
            Some(ForkResult::Parent { child }) => {
                if self.interactive {
                    let pgid = ctx.pgid.unwrap_or(child);
                    let _ = nix::unistd::setpgid(child, pgid);
                }
                ExitStatus::Running(child)
            }
            None => {
                print_err("nsh: failed to fork");
                ExitStatus::ExitedWith(1)
            }
        }
    }

    pub fn resolve_path(&self, name: &str) -> Option<String> {
        if name.starts_with('/') || name.starts_with("./") {
            return Some(name.to_owned());
        }
        self.path_table.get(name).cloned()
    }

    pub fn call_function(&mut self, body: &Command, args: &[String], ctx: &Context) -> ExitStatus {
        self.frames.push(Frame {
            vars: HashMap::new(),
            args: args.to_vec(),
        });
        let status = self.run_command(body, ctx);
        self.frames.pop();
        match status {
            ExitStatus::Return => ExitStatus::ExitedWith(0),
            other => other,
        }
    }

    /// Opens the files for redirections. Returns `(fd, target_fd)` pairs.
    fn open_redirects(
        &mut self,
        redirects: &[parser::Redirection],
        ctx: &Context,
        leak: bool,
    ) -> Option<Vec<(RawFd, RawFd)>> {
        let mut result = Vec::new();
        for redirect in redirects {
            match &redirect.target {
                RedirectionType::Fd(fd) => {
                    result.push((redirect.fd, *fd));
                }
                RedirectionType::File(word) => {
                    let path = self.expand_word_into_string(word, ctx).unwrap_or_default();
                    let file = match redirect.direction {
                        RedirectionDirection::Input => OpenOptions::new().read(true).open(&path),
                        RedirectionDirection::Output => OpenOptions::new()
                            .write(true)
                            .create(true)
                            .mode(0o644)
                            .open(&path),
                        RedirectionDirection::Append => {
                            OpenOptions::new().write(true).append(true).open(&path)
                        }
                    };
                    match file {
                        Ok(file) => {
                            if leak {
                                let fd = file.into_raw_fd();
                                result.push((redirect.fd, fd));
                            } else {
                                result.push((redirect.fd, file.into_raw_fd()));
                            }
                        }
                        Err(_) => {
                            crate::logger::warn(
                                "src/process.rs",
                                &format!("failed to open file: `{}'", path),
                            );
                            return None;
                        }
                    }
                }
                RedirectionType::HereDoc(heredoc) => {
                    let text = self.expand_heredoc(heredoc, ctx);
                    let (r, w) = process::pipe();
                    write_fd(w, text.as_bytes());
                    process::close(w);
                    result.push((redirect.fd, r));
                }
                RedirectionType::UnresolvedHereDoc(_) => {
                    crate::panic_at("src/process.rs:367:17", "internal error: entered unreachable code");
                }
            }
        }
        Some(result)
    }

    fn expand_heredoc(&mut self, heredoc: &HereDoc, ctx: &Context) -> String {
        let mut lines = Vec::new();
        for line in &heredoc.lines {
            let mut words = Vec::new();
            for word in line {
                words.push(self.expand_word_into_string(word, ctx).unwrap_or_default());
            }
            lines.push(words.join(" "));
        }
        let mut text = lines.join("\n");
        text.push('\n');
        text
    }

    // ------------------------------------------------------------------
    // Expansion
    // ------------------------------------------------------------------
    pub fn expand_words(&mut self, words: &[Word], ctx: &Context) -> Result<Vec<String>, ExpandError> {
        let mut result = Vec::new();
        for word in words {
            let fields = self.expand_word_into_vec(word, ctx)?;
            for (field, glob) in fields {
                if glob {
                    let matches = self.glob(&field)?;
                    result.extend(matches);
                } else {
                    result.push(field);
                }
            }
        }
        Ok(result)
    }

    fn glob(&self, pattern: &str) -> Result<Vec<String>, ExpandError> {
        match glob::glob(pattern) {
            Ok(paths) => {
                let mut result = Vec::new();
                for path in paths.flatten() {
                    result.push(path.to_string_lossy().into_owned());
                }
                if result.is_empty() {
                    Err(ExpandError::NoMatches)
                } else {
                    Ok(result)
                }
            }
            Err(err) => crate::panic_at("src/pattern.rs:73:41", &format!("failed to glob: {:?}", err)),
        }
    }

    pub fn expand_word_into_string(&mut self, word: &Word, ctx: &Context) -> Result<String, ExpandError> {
        let fields = self.expand_word_into_vec(word, ctx)?;
        Ok(fields.into_iter().map(|(s, _)| s).collect::<Vec<_>>().join(""))
    }

    fn home_dir(&self) -> String {
        dirs::home_dir()
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_default()
    }

    /// Expands a word into fields. Each field carries a flag telling whether
    /// it contains an unquoted glob character.
    pub fn expand_word_into_vec(&mut self, word: &Word, ctx: &Context) -> Result<Vec<(String, bool)>, ExpandError> {
        let mut words: Vec<(String, bool)> = Vec::new();
        let mut current = String::new();
        let mut glob = false;
        let split_ws = |s: &str| -> Vec<String> {
            s.split(|c| c == ' ' || c == '\t' || c == '\n')
                .map(|s| s.to_owned())
                .collect()
        };
        for span in &word.0 {
            match span {
                Span::Literal(s) => current.push_str(s),
                Span::Tilde(user) => {
                    if user.is_some() {
                        print_err("nsh: warning: ~user is not yet supported");
                    }
                    current.push_str(&self.home_dir());
                }
                Span::AnyString => {
                    current.push('*');
                    glob = true;
                }
                Span::AnyChar => {
                    current.push('?');
                    glob = true;
                }
                Span::ArithExpr { expr } => {
                    let value = self.evaluate_expr(expr);
                    current.push_str(&value.to_string());
                }
                Span::Parameter { name, op, quoted } => {
                    if name == "@" || name == "*" {
                        let args: Vec<String> = self.args().to_vec();
                        if *quoted {
                            if name == "*" {
                                current.push_str(&args.join(" "));
                            } else if args.is_empty() {
                                words.push((std::mem::take(&mut current), glob));
                                glob = false;
                            } else {
                                current.push_str(&args[0]);
                                words.push((std::mem::take(&mut current), glob));
                                glob = false;
                                for a in &args[1..] {
                                    words.push((a.clone(), false));
                                }
                            }
                        } else {
                            if !current.is_empty() {
                                words.push((std::mem::take(&mut current), glob));
                                glob = false;
                            }
                            if args.is_empty() {
                                words.push((String::new(), false));
                            }
                            for a in &args {
                                for f in split_ws(a) {
                                    words.push((f, false));
                                }
                            }
                        }
                        continue;
                    }
                    let value = self.expand_param(name, op, ctx)?;
                    if *quoted {
                        current.push_str(&value);
                    } else {
                        if !current.is_empty() {
                            words.push((std::mem::take(&mut current), glob));
                            glob = false;
                        }
                        for f in split_ws(&value) {
                            words.push((f, false));
                        }
                    }
                }
                Span::ArrayParameter { name, index, quoted } => {
                    let idx = self.evaluate_expr(index);
                    let value = match self.get_var(name) {
                        Some(var) if idx >= 0 => var.value_at(idx as usize).unwrap_or("").to_owned(),
                        _ => String::new(),
                    };
                    if *quoted {
                        current.push_str(&value);
                    } else {
                        if !current.is_empty() {
                            words.push((std::mem::take(&mut current), glob));
                            glob = false;
                        }
                        for f in split_ws(&value) {
                            words.push((f, false));
                        }
                    }
                }
                Span::Command { body, quoted } => {
                    let output = self.run_command_substitution(body, ctx);
                    if *quoted {
                        current.push_str(&output);
                    } else {
                        if !current.is_empty() {
                            words.push((std::mem::take(&mut current), glob));
                            glob = false;
                        }
                        for f in split_ws(&output) {
                            words.push((f, false));
                        }
                    }
                }
                Span::ProcSubst { body, output } => {
                    if *output {
                        crate::panic_at("src/expand.rs:238:25", "not implemented");
                    }
                    let fd = self.run_proc_subst(body, ctx);
                    current.push_str(&format!("/dev/fd/{}", fd));
                }
            }
        }
        if !current.is_empty() || words.is_empty() {
            words.push((current, glob));
        }
        Ok(words)
    }

    fn get_special_or_var(&self, name: &str) -> Option<String> {
        match name {
            "?" => Some(self.last_status.to_string()),
            "$" => Some(process::getpid().as_raw().to_string()),
            "!" => Some(self.last_back_pid.to_string()),
            "#" => {
                let n = (1..=9).filter(|i| self.args().get(*i - 1).is_some()).count();
                Some(n.to_string())
            }
            "-" => Some(String::new()),
            "0" => Some(self.script_name.clone()),
            "@" | "*" => Some(self.args().join(" ")),
            _ => {
                if let Ok(n) = name.parse::<usize>() {
                    return Some(self.args().get(n - 1).cloned().unwrap_or_default());
                }
                self.get_var(name).map(|v| v.as_str().to_owned())
            }
        }
    }

    fn is_special(name: &str) -> bool {
        matches!(name, "?" | "$" | "!" | "#" | "-" | "@" | "*")
    }

    fn expand_param(&mut self, name: &str, op: &ExpansionOp, ctx: &Context) -> Result<String, ExpandError> {
        let value = self.get_special_or_var(name);
        if Self::is_special(name) {
            return Ok(value.unwrap_or_default());
        }
        match op {
            ExpansionOp::Length => Ok(value.map(|v| v.chars().count()).unwrap_or(0).to_string()),
            ExpansionOp::GetOrEmpty => {
                match value {
                    Some(v) => Ok(v),
                    None => {
                        if self.nounset {
                            print_err(&format!("nsh: undefined variable `{}'", name));
                            self.exit(1);
                        }
                        Ok(String::new())
                    }
                }
            }
            ExpansionOp::GetOrDefault(default) | ExpansionOp::GetNullableOrDefault(default) => match value {
                Some(v) => Ok(v),
                None => self.expand_word_into_string(default, ctx),
            },
            ExpansionOp::GetOrDefaultAndAssign(default)
            | ExpansionOp::GetNullableOrDefaultAndAssign(default) => match value {
                Some(v) => Ok(v),
                None => {
                    let v = self.expand_word_into_string(default, ctx)?;
                    self.set_str(name, &v);
                    Ok(v)
                }
            },
            ExpansionOp::Subst {
                pattern,
                replacement,
                replace_all,
            } => {
                let value = value.unwrap_or_default();
                let pat = self.word_to_pattern(pattern, ctx, false);
                let rep = self.word_to_pattern(replacement, ctx, true);
                Ok(pat.replace(&value, &rep, *replace_all))
            }
        }
    }

    /// Converts a word into a pattern. Literal spans of a replacement are
    /// emitted rather than matched.
    pub fn word_to_pattern(&mut self, word: &Word, ctx: &Context, replacement: bool) -> Pattern {
        let mut spans = Vec::new();
        for span in &word.0 {
            match span {
                Span::Literal(s) => {
                    if replacement {
                        spans.push(PatternSpan::Emit(s.clone()));
                    } else {
                        spans.push(PatternSpan::Literal(s.clone()));
                    }
                }
                Span::AnyString => spans.push(PatternSpan::AnyString),
                Span::AnyChar => spans.push(PatternSpan::AnyChar),
                other => {
                    let w = Word(vec![other.clone()]);
                    let s = self.expand_word_into_string(&w, ctx).unwrap_or_default();
                    if !s.is_empty() {
                        spans.push(PatternSpan::Literal(s));
                    }
                }
            }
        }
        Pattern { spans }
    }

    fn run_command_substitution(&mut self, body: &[Term], ctx: &Context) -> String {
        let (r, w) = process::pipe();
        use std::io::Write;
        let _ = std::io::stdout().flush();
        match process::fork() {
            Some(ForkResult::Child) => {
                process::close(r);
                let child_ctx = Context {
                    stdin: ctx.stdin,
                    stdout: w,
                    stderr: ctx.stderr,
                    pgid: None,
                    background: false,
                    interactive: ctx.interactive,
                };
                self.interactive = false;
                let status = self.run_terms(body, &child_ctx);
                let code = match status {
                    ExitStatus::ExitedWith(c) => c,
                    _ => 0,
                };
                self.exit(code);
            }
            Some(ForkResult::Parent { child }) => {
                process::close(w);
                let mut output = Vec::new();
                let mut buf = [0u8; 4096];
                loop {
                    match nix::unistd::read(r, &mut buf) {
                        Ok(0) => break,
                        Ok(n) => output.extend_from_slice(&buf[..n]),
                        Err(nix::Error::EINTR) => continue,
                        Err(_) => break,
                    }
                }
                process::close(r);
                let _ = process::wait_pid(child);
                let mut s = match String::from_utf8(output) {
                    Ok(s) => s,
                    Err(e) => crate::panic_at(
                        "src/utils.rs:43:42",
                        &format!("binary data is not yet supported: {:?}", e),
                    ),
                };
                while s.ends_with('\n') {
                    s.pop();
                }
                s
            }
            None => String::new(),
        }
    }

    fn run_proc_subst(&mut self, body: &[Term], ctx: &Context) -> RawFd {
        let (r, w) = process::pipe();
        use std::io::Write;
        let _ = std::io::stdout().flush();
        match process::fork() {
            Some(ForkResult::Child) => {
                process::close(r);
                let child_ctx = Context {
                    stdin: ctx.stdin,
                    stdout: w,
                    stderr: ctx.stderr,
                    pgid: None,
                    background: false,
                    interactive: ctx.interactive,
                };
                self.interactive = false;
                let status = self.run_terms(body, &child_ctx);
                let code = match status {
                    ExitStatus::ExitedWith(c) => c,
                    _ => 0,
                };
                self.exit(code);
            }
            Some(ForkResult::Parent { .. }) => {
                process::close(w);
                r
            }
            None => r,
        }
    }

    // ------------------------------------------------------------------
    // Arithmetic
    // ------------------------------------------------------------------
    pub fn evaluate_expr(&mut self, expr: &Expr) -> i32 {
        match expr {
            Expr::Literal(n) => *n,
            Expr::Parameter { name } => self.get_str(name).parse::<i32>().unwrap_or(0),
            Expr::Inc(name) => {
                let v = self.get_str(name).parse::<i32>().unwrap_or(0).wrapping_add(1);
                self.set_str(name, &v.to_string());
                v
            }
            Expr::Dec(name) => {
                let v = self.get_str(name).parse::<i32>().unwrap_or(0).wrapping_sub(1);
                self.set_str(name, &v.to_string());
                v
            }
            Expr::Assign { name, rhs } => {
                let v = self.evaluate_expr(rhs);
                self.set_str(name, &v.to_string());
                v
            }
            Expr::Binary(op, lhs, rhs) => {
                let l = self.evaluate_expr(lhs);
                let r = self.evaluate_expr(rhs);
                match op {
                    BinaryExpr::Add => l.wrapping_add(r),
                    BinaryExpr::Sub => l.wrapping_sub(r),
                    BinaryExpr::Mul => l.wrapping_mul(r),
                    BinaryExpr::Div => {
                        if r == 0 {
                            crate::panic_at("src/eval.rs:38:47", "attempt to divide by zero");
                        }
                        l.wrapping_div(r)
                    }
                    BinaryExpr::Eq => (l == r) as i32,
                    BinaryExpr::Ne => (l != r) as i32,
                    BinaryExpr::Lt => (l < r) as i32,
                    BinaryExpr::Le => (l <= r) as i32,
                    BinaryExpr::Gt => (l > r) as i32,
                    BinaryExpr::Ge => (l >= r) as i32,
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // Misc
    // ------------------------------------------------------------------
    pub fn run_file(&mut self, path: &Path, ctx: &Context) -> i32 {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                print_err(&format!("nsh: failed open the file: {:?}", e));
                return 1;
            }
        };
        match parser::parse(&content) {
            Ok(ast) => {
                let status = self.run_ast(&ast, ctx);
                match status {
                    ExitStatus::ExitedWith(c) => c,
                    ExitStatus::Return => crate::panic_at("src/main.rs:133:14", "unexpected Return"),
                    ExitStatus::Break => crate::panic_at("src/main.rs:133:14", "unexpected Break"),
                    ExitStatus::Continue => crate::panic_at("src/main.rs:133:14", "unexpected Continue"),
                    ExitStatus::Running(_) => 0,
                }
            }
            Err(err) => {
                print_err(&format!("nsh: parse error: {}", err));
                -1
            }
        }
    }
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/shell.rs <<'EOF'
//! The shell state and the interpreter.
use crate::parser::{
    self, Ast, Assignment, BinaryExpr, Command, ExpansionOp, Expr, HereDoc, Initializer,
    LocalDeclaration, Pipeline, RedirectionDirection, RedirectionType, RunIf, Span, Term, Word,
};
use crate::pattern::{Pattern, PatternSpan};
use crate::process::{self, Job, ProcessState, Waited};
use crate::variable::{Frame, Value, Variable};
use nix::unistd::{ForkResult, Pid};
use std::collections::HashMap;
use std::fs::{File, OpenOptions};
use std::io::IsTerminal;
use std::os::unix::fs::OpenOptionsExt;
use std::os::unix::io::{IntoRawFd, RawFd};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ExitStatus {
    ExitedWith(i32),
    Running(Pid),
    Break,
    Continue,
    Return,
}

#[derive(Debug, Clone, Copy)]
pub struct Context {
    pub stdin: RawFd,
    pub stdout: RawFd,
    pub stderr: RawFd,
    pub pgid: Option<Pid>,
    pub background: bool,
    pub interactive: bool,
}

pub enum ExpandError {
    NoMatches,
}

pub struct Shell {
    pub vars: HashMap<String, Variable>,
    pub frames: Vec<Frame>,
    pub functions: HashMap<String, Command>,
    pub aliases: Vec<(String, String)>,
    pub path_table: HashMap<String, String>,
    pub last_status: i32,
    pub last_back_pid: i32,
    pub dir_stack: Vec<PathBuf>,
    pub errexit: bool,
    pub nounset: bool,
    pub noexec: bool,
    pub interactive: bool,
    pub script_name: String,
    pub jobs: Vec<Job>,
    pub last_fore_job: Option<usize>,
    pub shell_pgid: Pid,
    /// Files opened for redirections of external commands (intentionally kept
    /// open, mirroring the original implementation).
    pub leaked_files: Vec<File>,
    pub exiting: Option<i32>,
    pub history_hook: Option<Box<dyn FnMut(&str)>>,
}

pub fn print_err(msg: &str) {
    use std::io::Write;
    let _ = std::io::stdout().flush();
    if std::io::stderr().is_terminal() {
        eprintln!("\x1b[1m\x1b[38;5;11m{}\x1b[0m", msg);
    } else {
        eprintln!("{}", msg);
    }
}

fn write_fd(fd: RawFd, data: &[u8]) -> bool {
    let mut written = 0;
    while written < data.len() {
        match nix::unistd::write(unsafe { std::os::fd::BorrowedFd::borrow_raw(fd) }, &data[written..]) {
            Ok(n) => written += n,
            Err(nix::Error::EINTR) => continue,
            Err(e) => {
                if e == nix::Error::ENOSPC {
                    crate::panic_at("src/utils.rs:51:47", "failed to write: ENOSPC");
                }
                return false;
            }
        }
    }
    true
}

pub fn write_to_fd(fd: RawFd, s: &str) {
    write_fd(fd, s.as_bytes());
}

impl Shell {
    pub fn new(interactive: bool) -> Shell {
        let mut vars = HashMap::new();
        for (k, v) in std::env::vars() {
            vars.insert(k, Variable::new(Value::String(v)));
        }
        if !vars.contains_key("PATH") {
            vars.insert(
                "PATH".to_owned(),
                Variable::new(Value::String(
                    "/sbin:/usr/sbin:/usr/local/sbin:/bin:/usr/bin:/usr/local/bin".to_owned(),
                )),
            );
        }
        let mut shell = Shell {
            vars,
            frames: Vec::new(),
            functions: HashMap::new(),
            aliases: Vec::new(),
            path_table: HashMap::new(),
            last_status: 0,
            last_back_pid: 0,
            dir_stack: Vec::new(),
            errexit: false,
            nounset: false,
            noexec: false,
            interactive,
            script_name: String::new(),
            jobs: Vec::new(),
            last_fore_job: None,
            shell_pgid: nix::unistd::getpgrp(),
            leaked_files: Vec::new(),
            exiting: None,
            history_hook: None,
        };
        shell.rebuild_path_table();
        shell
    }

    pub fn rebuild_path_table(&mut self) {
        let path = self.get_str("PATH");
        self.path_table.clear();
        for dir in path.split(':') {
            if dir.is_empty() {
                continue;
            }
            if let Ok(entries) = std::fs::read_dir(dir) {
                for entry in entries.flatten() {
                    let name = entry.file_name().to_string_lossy().into_owned();
                    let full = format!("{}/{}", dir, name);
                    self.path_table.entry(name).or_insert(full);
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // Variables
    // ------------------------------------------------------------------
    pub fn get_var(&self, name: &str) -> Option<&Variable> {
        if let Some(frame) = self.frames.last() {
            if let Some(v) = frame.vars.get(name) {
                return Some(v);
            }
        }
        self.vars.get(name)
    }

    pub fn get_str(&self, name: &str) -> String {
        self.get_var(name).map(|v| v.as_str().to_owned()).unwrap_or_default()
    }

    /// Sets a variable: a local one if it exists in the current frame,
    /// otherwise a global one.
    pub fn set_value(&mut self, name: &str, value: Value) {
        if let Some(frame) = self.frames.last_mut() {
            if let Some(v) = frame.vars.get_mut(name) {
                v.value = value;
                return;
            }
        }
        let exported = self.vars.get(name).map(|v| v.exported).unwrap_or(false);
        if exported {
            if let Value::String(ref s) = value {
                std::env::set_var(name, s);
            }
        }
        self.vars.insert(
            name.to_owned(),
            Variable {
                value,
                exported,
            },
        );
    }

    pub fn set_str(&mut self, name: &str, value: &str) {
        self.set_value(name, Value::String(value.to_owned()));
    }

    pub fn set_global_str(&mut self, name: &str, value: &str) {
        let exported = self.vars.get(name).map(|v| v.exported).unwrap_or(false);
        if exported {
            std::env::set_var(name, value);
        }
        self.vars.insert(
            name.to_owned(),
            Variable {
                value: Value::String(value.to_owned()),
                exported,
            },
        );
    }

    pub fn set_local(&mut self, name: &str, value: Value) -> bool {
        if let Some(frame) = self.frames.last_mut() {
            frame.vars.insert(name.to_owned(), Variable::new(value));
            true
        } else {
            false
        }
    }

    pub fn export(&mut self, name: &str) {
        let value = self.get_str(name);
        std::env::set_var(name, &value);
        if let Some(v) = self.vars.get_mut(name) {
            v.exported = true;
        } else {
            self.vars.insert(
                name.to_owned(),
                Variable {
                    value: Value::String(value),
                    exported: true,
                },
            );
        }
    }

    pub fn unset(&mut self, name: &str) {
        if let Some(frame) = self.frames.last_mut() {
            frame.vars.remove(name);
        }
        if let Some(v) = self.vars.remove(name) {
            if v.exported {
                std::env::remove_var(name);
            }
        }
    }

    pub fn args(&self) -> &[String] {
        match self.frames.last() {
            Some(frame) => &frame.args,
            None => &[],
        }
    }

    pub fn current_dir(&self) -> PathBuf {
        match std::env::current_dir() {
            Ok(p) => p,
            Err(e) => crate::panic_at(
                "src/builtins/cd.rs:8:43",
                &format!("failed to getcwd(): {:?}", e),
            ),
        }
    }

    // ------------------------------------------------------------------
    // Execution
    // ------------------------------------------------------------------
    pub fn run_script(&mut self, script: &str, ctx: &Context) -> ExitStatus {
        match parser::parse(script) {
            Ok(ast) => self.run_ast(&ast, ctx),
            Err(err) => {
                print_err(&format!("nsh: parse error: {}", err));
                self.last_status = -1;
                ExitStatus::ExitedWith(-1)
            }
        }
    }

    pub fn run_ast(&mut self, ast: &Ast, ctx: &Context) -> ExitStatus {
        self.run_terms(&ast.terms, ctx)
    }

    pub fn run_terms(&mut self, terms: &[Term], ctx: &Context) -> ExitStatus {
        let mut last = ExitStatus::ExitedWith(0);
        for term in terms {
            for pipeline in &term.pipelines {
                let should_run = match pipeline.run_if {
                    RunIf::Always => true,
                    RunIf::Success => self.last_status == 0,
                    // The original implementation runs the `||` side
                    // unconditionally.
                    RunIf::Failure => true,
                };
                if !should_run {
                    continue;
                }
                let mut ctx2 = *ctx;
                ctx2.background = term.background;
                last = self.run_pipeline(pipeline, &ctx2, &term.code);
                match last {
                    ExitStatus::ExitedWith(status) => {
                        self.last_status = status;
                        if self.errexit && status != 0 {
                            self.exit(status);
                        }
                    }
                    ExitStatus::Break | ExitStatus::Continue | ExitStatus::Return => {
                        return last;
                    }
                    ExitStatus::Running(_) => {}
                }
                if let Some(code) = self.exiting {
                    self.exit(code);
                }
            }
        }
        last
    }

    pub fn exit(&mut self, status: i32) -> ! {
        use std::io::Write;
        let _ = std::io::stdout().flush();
        std::process::exit(status);
    }

    fn run_pipeline(&mut self, pipeline: &Pipeline, ctx: &Context, code: &str) -> ExitStatus {
        let mut last_status = ExitStatus::ExitedWith(0);
        let mut pids: Vec<Pid> = Vec::new();
        let mut pgid: Option<Pid> = ctx.pgid;
        let mut stdin = ctx.stdin;
        let n = pipeline.commands.len();
        for (i, command) in pipeline.commands.iter().enumerate() {
            let is_last = i + 1 == n;
            let (stdout, pipe_w, pipe_r) = if is_last {
                (ctx.stdout, None, None)
            } else {
                let (r, w) = process::pipe();
                (w, Some(w), Some(r))
            };
            let cmd_ctx = Context {
                stdin,
                stdout,
                stderr: ctx.stderr,
                pgid,
                background: ctx.background,
                interactive: ctx.interactive,
            };
            let result = self.run_command(command, &cmd_ctx);
            if let ExitStatus::Running(pid) = result {
                if pgid.is_none() {
                    pgid = Some(pid);
                }
                pids.push(pid);
            }
            last_status = result;
            if let Some(w) = pipe_w {
                process::close(w);
            }
            // NOTE: the read end is intentionally not closed in the parent
            // (mirrors the original implementation).
            if let Some(r) = pipe_r {
                stdin = r;
            }
            match result {
                ExitStatus::Break | ExitStatus::Continue | ExitStatus::Return => {
                    if pids.is_empty() {
                        return result;
                    }
                }
                _ => {}
            }
        }

        if pids.is_empty() {
            return last_status;
        }

        // Create a job for the external processes.
        let job_id = self.alloc_job_id();
        let job = Job {
            id: job_id,
            pgid: pgid.unwrap(),
            cmd: code.to_owned(),
            processes: pids.clone(),
            states: vec![ProcessState::Running; pids.len()],
        };
        self.jobs.push(job);
        let is_external_last = matches!(last_status, ExitStatus::Running(_));

        if ctx.background && self.interactive {
            self.last_back_pid = pids.last().unwrap().as_raw();
            return ExitStatus::ExitedWith(0);
        }

        if ctx.background {
            self.last_back_pid = pids.last().unwrap().as_raw();
        }

        let status = self.wait_for_job(job_id, ctx);
        if ctx.background {
            // Report the completion of the "background" job immediately.
            self.check_jobs();
            return ExitStatus::ExitedWith(status);
        }
        if is_external_last {
            ExitStatus::ExitedWith(status)
        } else {
            match last_status {
                ExitStatus::Running(_) => ExitStatus::ExitedWith(status),
                other => other,
            }
        }
    }

    fn alloc_job_id(&self) -> usize {
        let mut id = 1;
        while self.jobs.iter().any(|j| j.id == id) {
            id += 1;
        }
        id
    }

    pub fn find_job_mut(&mut self, pid: Pid) -> Option<(&mut Job, usize)> {
        for job in self.jobs.iter_mut() {
            if let Some(idx) = job.processes.iter().position(|p| *p == pid) {
                return Some((job, idx));
            }
        }
        None
    }

    /// Waits until the job is completed or stopped. Returns its exit status.
    pub fn wait_for_job(&mut self, job_id: usize, ctx: &Context) -> i32 {
        if self.interactive {
            if let Some(job) = self.jobs.iter().find(|j| j.id == job_id) {
                process::set_terminal_pgid(0, job.pgid);
            }
        }
        loop {
            let done = match self.jobs.iter().find(|j| j.id == job_id) {
                Some(job) => job.is_completed() || job.is_stopped(),
                None => true,
            };
            if done {
                break;
            }
            match process::wait_any(false) {
                Waited::Exited(pid, status) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(status);
                    }
                }
                Waited::Signaled(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(-1);
                    }
                }
                Waited::Stopped(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Stopped(pid);
                    }
                }
                Waited::NoChild => break,
                Waited::Other => {}
            }
        }
        if self.interactive {
            process::set_terminal_pgid(0, self.shell_pgid);
        }
        let _ = ctx;
        let (status, completed, stopped, cmd) = match self.jobs.iter().find(|j| j.id == job_id) {
            Some(job) => (job.last_status(), job.is_completed(), job.is_stopped(), job.cmd.clone()),
            None => (0, true, false, String::new()),
        };
        if stopped {
            print_err(&format!("nsh: [{}] Stopped: {}", job_id, cmd));
            self.last_fore_job = Some(job_id);
            return 0;
        }
        if completed && !ctx.background {
            self.jobs.retain(|j| j.id != job_id);
        }
        status
    }

    /// Reaps finished background jobs and reports them.
    pub fn check_jobs(&mut self) {
        loop {
            match process::wait_any(true) {
                Waited::Exited(pid, status) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(status);
                    }
                }
                Waited::Signaled(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Completed(-1);
                    }
                }
                Waited::Stopped(pid) => {
                    if let Some((job, idx)) = self.find_job_mut(pid) {
                        job.states[idx] = ProcessState::Stopped(pid);
                    }
                }
                _ => break,
            }
        }
        let completed: Vec<Job> = self.jobs.iter().filter(|j| j.is_completed()).cloned().collect();
        for job in completed {
            println!("[{}] Done: {}", job.id, job.cmd);
            self.jobs.retain(|j| j.id != job.id);
        }
        let _ = std::io::Write::flush(&mut std::io::stdout());
    }

    pub fn run_command(&mut self, command: &Command, ctx: &Context) -> ExitStatus {
        if let Some(code) = self.exiting {
            self.exit(code);
        }
        match command {
            Command::SimpleCommand {
                argv,
                redirects,
                assignments,
            } => self.run_simple_command(argv, redirects, assignments, ctx),
            Command::Assignment { assignments } => {
                for assignment in assignments {
                    let value = self.evaluate_initializer(&assignment.initializer, ctx);
                    self.set_value(&assignment.name, value);
                }
                ExitStatus::ExitedWith(0)
            }
            Command::If {
                condition,
                then_part,
                elif_parts,
                else_part,
            } => {
                let cond = self.run_terms(condition, ctx);
                if let ExitStatus::ExitedWith(0) = cond {
                    return self.run_terms(then_part, ctx);
                }
                if !matches!(cond, ExitStatus::ExitedWith(_)) {
                    return cond;
                }
                for elif in elif_parts {
                    let cond = self.run_terms(&elif.condition, ctx);
                    if let ExitStatus::ExitedWith(0) = cond {
                        // The original implementation runs the main then-part.
                        return self.run_terms(then_part, ctx);
                    }
                    if !matches!(cond, ExitStatus::ExitedWith(_)) {
                        return cond;
                    }
                }
                if let Some(else_part) = else_part {
                    return self.run_terms(else_part, ctx);
                }
                ExitStatus::ExitedWith(0)
            }
            Command::While { condition, body } => {
                let mut last = ExitStatus::ExitedWith(0);
                loop {
                    let cond = self.run_terms(condition, ctx);
                    match cond {
                        ExitStatus::ExitedWith(0) => {}
                        ExitStatus::ExitedWith(_) => break,
                        other => return other,
                    }
                    last = self.run_terms(body, ctx);
                }
                last
            }
            Command::For {
                var_name,
                words,
                body,
            } => {
                let values = match self.expand_words(words, ctx) {
                    Ok(v) => v,
                    Err(_) => return ExitStatus::ExitedWith(1),
                };
                for value in values {
                    self.set_str(var_name, &value);
                    match self.run_terms(body, ctx) {
                        ExitStatus::Break => break,
                        ExitStatus::Continue => continue,
                        ExitStatus::Return => return ExitStatus::Return,
                        _ => {}
                    }
                }
                ExitStatus::ExitedWith(0)
            }
            Command::ArithFor {
                init,
                cond,
                update,
                body,
            } => {
                self.evaluate_expr(init);
                loop {
                    if self.evaluate_expr(cond) != 1 {
                        break;
                    }
                    match self.run_terms(body, ctx) {
                        ExitStatus::Break => break,
                        ExitStatus::Continue => {}
                        ExitStatus::Return => return ExitStatus::Return,
                        _ => {}
                    }
                    self.evaluate_expr(update);
                }
                ExitStatus::ExitedWith(0)
            }
            Command::Case { word, cases } => {
                let value = match self.expand_word_into_string(word, ctx) {
                    Ok(v) => v,
                    Err(_) => return ExitStatus::ExitedWith(1),
                };
                for case in cases {
                    for pattern_word in &case.patterns {
                        let pattern = self.word_to_pattern(pattern_word, ctx, false);
                        if pattern.matches(&value) {
                            return self.run_terms(&case.body, ctx);
                        }
                    }
                }
                ExitStatus::ExitedWith(0)
            }
            Command::FunctionDef { name, body } => {
                self.functions.insert(name.clone(), (**body).clone());
                ExitStatus::ExitedWith(0)
            }
            Command::LocalDef { declarations } => {
                if self.frames.is_empty() {
                    print_err("nsh: local variable can only be used in a function");
                    return ExitStatus::ExitedWith(1);
                }
                for decl in declarations {
                    match decl {
                        LocalDeclaration::Assignment(assignment) => {
                            let value = self.evaluate_initializer(&assignment.initializer, ctx);
                            self.set_local(&assignment.name, value);
                        }
                        LocalDeclaration::Name(name) => {
                            self.set_local(name, Value::String(String::new()));
                        }
                    }
                }
                ExitStatus::ExitedWith(0)
            }
            Command::Group { terms } => self.run_terms(terms, ctx),
            Command::SubShellGroup { terms } => {
                match process::fork() {
                    Some(ForkResult::Child) => {
                        let status = self.run_terms(terms, ctx);
                        let code = match status {
                            ExitStatus::ExitedWith(c) => c,
                            _ => 0,
                        };
                        self.exit(code);
                    }
                    Some(ForkResult::Parent { child }) => {
                        let status = match process::wait_pid(child) {
                            Waited::Exited(_, s) => s,
                            Waited::Signaled(_) => -1,
                            _ => 0,
                        };
                        ExitStatus::ExitedWith(status)
                    }
                    None => ExitStatus::ExitedWith(1),
                }
            }
            Command::Return { .. } => ExitStatus::Return,
            Command::Break => ExitStatus::Break,
            Command::Continue => ExitStatus::Continue,
        }
    }

    fn evaluate_initializer(&mut self, initializer: &Initializer, ctx: &Context) -> Value {
        match initializer {
            Initializer::String(word) => {
                let s = self.expand_word_into_string(word, ctx).unwrap_or_default();
                Value::String(s)
            }
            Initializer::Array(words) => {
                let elems = self.expand_words(words, ctx).unwrap_or_default();
                Value::Array(elems)
            }
        }
    }

    fn run_simple_command(
        &mut self,
        argv: &[Word],
        redirects: &[parser::Redirection],
        assignments: &[Assignment],
        ctx: &Context,
    ) -> ExitStatus {
        let mut args = match self.expand_words(argv, ctx) {
            Ok(a) => a,
            Err(ExpandError::NoMatches) => {
                print_err("nsh: error: no matches");
                return ExitStatus::ExitedWith(1);
            }
        };
        if args.is_empty() {
            return ExitStatus::ExitedWith(0);
        }

        // Alias expansion.
        if let Some(body) = self.aliases.iter().find(|(n, _)| *n == args[0]).map(|(_, b)| b.clone()) {
            let mut new_args: Vec<String> = body.trim().split(' ').map(|s| s.to_owned()).collect();
            new_args.extend(args.drain(1..));
            args = new_args;
        }

        // Temporary assignments (for external commands).
        let mut env_assignments: Vec<(String, String)> = Vec::new();
        for assignment in assignments {
            let value = self.evaluate_initializer(&assignment.initializer, ctx);
            let s = match value {
                Value::String(s) => s,
                Value::Array(a) => a.first().cloned().unwrap_or_default(),
            };
            env_assignments.push((assignment.name.clone(), s));
        }

        // Functions.
        if let Some(body) = self.functions.get(&args[0]).cloned() {
            return self.call_function(&body, &args[1..], ctx);
        }

        // Builtins.
        if crate::builtins::is_builtin(&args[0]) {
            let fds = match self.open_redirects(redirects, ctx, false) {
                Some(fds) => fds,
                None => return ExitStatus::ExitedWith(1),
            };
            let mut bctx = *ctx;
            for (fd, target) in &fds {
                match *fd {
                    0 => bctx.stdin = *target,
                    1 => bctx.stdout = *target,
                    2 => bctx.stderr = *target,
                    _ => {}
                }
            }
            let status = crate::builtins::run_builtin(self, &args, &bctx);
            for (_, target) in fds {
                if target != ctx.stdin && target != ctx.stdout && target != ctx.stderr {
                    process::close(target);
                }
            }
            return status;
        }

        // External commands.
        let path = match self.resolve_path(&args[0]) {
            Some(p) => p,
            None => {
                print_err(&format!("nsh: command not found `{}'", args[0]));
                return ExitStatus::ExitedWith(1);
            }
        };

        let fds = match self.open_redirects(redirects, ctx, true) {
            Some(fds) => fds,
            None => return ExitStatus::ExitedWith(1),
        };

        let mut env: Vec<String> = std::env::vars().map(|(k, v)| format!("{}={}", k, v)).collect();
        for (k, v) in &env_assignments {
            env.retain(|e| !e.starts_with(&format!("{}=", k)));
            env.push(format!("{}={}", k, v));
        }

        use std::io::Write;
        let _ = std::io::stdout().flush();
        match process::fork() {
            Some(ForkResult::Child) => {
                let pid = process::getpid();
                if self.interactive {
                    let pgid = ctx.pgid.unwrap_or(pid);
                    let _ = nix::unistd::setpgid(pid, pgid);
                    if !ctx.background {
                        process::set_terminal_pgid(0, pgid);
                    }
                }
                process::restore_signals();
                if ctx.stdin != 0 {
                    process::dup2(ctx.stdin, 0);
                }
                if ctx.stdout != 1 {
                    process::dup2(ctx.stdout, 1);
                }
                if ctx.stderr != 2 {
                    process::dup2(ctx.stderr, 2);
                }
                for (fd, target) in &fds {
                    process::dup2(*target, *fd);
                }
                let err = process::execv(&path, &args, &env);
                let msg = match err {
                    nix::Error::EACCES => {
                        format!("nsh: Failed to exec \"{}\" (EACCESS). chmod(1) may help.", path)
                    }
                    e => format!("nsh: Failed to exec \"{}\" ({})", path, e),
                };
                print_err(&msg);
                std::process::exit(1);
            }
            Some(ForkResult::Parent { child }) => {
                if self.interactive {
                    let pgid = ctx.pgid.unwrap_or(child);
                    let _ = nix::unistd::setpgid(child, pgid);
                }
                ExitStatus::Running(child)
            }
            None => {
                print_err("nsh: failed to fork");
                ExitStatus::ExitedWith(1)
            }
        }
    }

    pub fn resolve_path(&self, name: &str) -> Option<String> {
        if name.starts_with('/') || name.starts_with("./") {
            return Some(name.to_owned());
        }
        self.path_table.get(name).cloned()
    }

    pub fn call_function(&mut self, body: &Command, args: &[String], ctx: &Context) -> ExitStatus {
        self.frames.push(Frame {
            vars: HashMap::new(),
            args: args.to_vec(),
        });
        let status = self.run_command(body, ctx);
        self.frames.pop();
        match status {
            ExitStatus::Return => ExitStatus::ExitedWith(0),
            other => other,
        }
    }

    /// Opens the files for redirections. Returns `(fd, target_fd)` pairs.
    fn open_redirects(
        &mut self,
        redirects: &[parser::Redirection],
        ctx: &Context,
        leak: bool,
    ) -> Option<Vec<(RawFd, RawFd)>> {
        let mut result = Vec::new();
        for redirect in redirects {
            match &redirect.target {
                RedirectionType::Fd(fd) => {
                    result.push((redirect.fd, *fd));
                }
                RedirectionType::File(word) => {
                    let path = self.expand_word_into_string(word, ctx).unwrap_or_default();
                    let file = match redirect.direction {
                        RedirectionDirection::Input => OpenOptions::new().read(true).open(&path),
                        RedirectionDirection::Output => OpenOptions::new()
                            .write(true)
                            .create(true)
                            .mode(0o644)
                            .open(&path),
                        RedirectionDirection::Append => {
                            OpenOptions::new().write(true).append(true).open(&path)
                        }
                    };
                    match file {
                        Ok(file) => {
                            if leak {
                                let fd = file.into_raw_fd();
                                result.push((redirect.fd, fd));
                            } else {
                                result.push((redirect.fd, file.into_raw_fd()));
                            }
                        }
                        Err(_) => {
                            crate::logger::warn(
                                "src/process.rs",
                                &format!("failed to open file: `{}'", path),
                            );
                            return None;
                        }
                    }
                }
                RedirectionType::HereDoc(heredoc) => {
                    let text = self.expand_heredoc(heredoc, ctx);
                    let (r, w) = process::pipe();
                    write_fd(w, text.as_bytes());
                    process::close(w);
                    result.push((redirect.fd, r));
                }
                RedirectionType::UnresolvedHereDoc(_) => {
                    crate::panic_at("src/process.rs:367:17", "internal error: entered unreachable code");
                }
            }
        }
        Some(result)
    }

    fn expand_heredoc(&mut self, heredoc: &HereDoc, ctx: &Context) -> String {
        let mut lines = Vec::new();
        for line in &heredoc.lines {
            let mut words = Vec::new();
            for word in line {
                words.push(self.expand_word_into_string(word, ctx).unwrap_or_default());
            }
            lines.push(words.join(" "));
        }
        let mut text = lines.join("\n");
        text.push('\n');
        text
    }

    // ------------------------------------------------------------------
    // Expansion
    // ------------------------------------------------------------------
    pub fn expand_words(&mut self, words: &[Word], ctx: &Context) -> Result<Vec<String>, ExpandError> {
        let mut result = Vec::new();
        for word in words {
            let fields = self.expand_word_into_vec(word, ctx)?;
            for (field, glob) in fields {
                if glob {
                    let matches = self.glob(&field)?;
                    result.extend(matches);
                } else {
                    result.push(field);
                }
            }
        }
        Ok(result)
    }

    fn glob(&self, pattern: &str) -> Result<Vec<String>, ExpandError> {
        match glob::glob(pattern) {
            Ok(paths) => {
                let mut result = Vec::new();
                for path in paths.flatten() {
                    result.push(path.to_string_lossy().into_owned());
                }
                if result.is_empty() {
                    Err(ExpandError::NoMatches)
                } else {
                    Ok(result)
                }
            }
            Err(err) => crate::panic_at("src/pattern.rs:73:41", &format!("failed to glob: {:?}", err)),
        }
    }

    pub fn expand_word_into_string(&mut self, word: &Word, ctx: &Context) -> Result<String, ExpandError> {
        let fields = self.expand_word_into_vec(word, ctx)?;
        Ok(fields.into_iter().map(|(s, _)| s).collect::<Vec<_>>().join(""))
    }

    fn home_dir(&self) -> String {
        dirs::home_dir()
            .map(|p| p.to_string_lossy().into_owned())
            .unwrap_or_default()
    }

    /// Expands a word into fields. Each field carries a flag telling whether
    /// it contains an unquoted glob character.
    pub fn expand_word_into_vec(&mut self, word: &Word, ctx: &Context) -> Result<Vec<(String, bool)>, ExpandError> {
        let mut words: Vec<(String, bool)> = Vec::new();
        let mut current = String::new();
        let mut glob = false;
        let split_ws = |s: &str| -> Vec<String> {
            s.split(|c| c == ' ' || c == '\t' || c == '\n')
                .map(|s| s.to_owned())
                .collect()
        };
        for span in &word.0 {
            match span {
                Span::Literal(s) => current.push_str(s),
                Span::Tilde(user) => {
                    if user.is_some() {
                        print_err("nsh: warning: ~user is not yet supported");
                    }
                    current.push_str(&self.home_dir());
                }
                Span::AnyString => {
                    current.push('*');
                    glob = true;
                }
                Span::AnyChar => {
                    current.push('?');
                    glob = true;
                }
                Span::ArithExpr { expr } => {
                    let value = self.evaluate_expr(expr);
                    current.push_str(&value.to_string());
                }
                Span::Parameter { name, op, quoted } => {
                    if name == "@" || name == "*" {
                        let args: Vec<String> = self.args().to_vec();
                        if *quoted {
                            if name == "*" {
                                current.push_str(&args.join(" "));
                            } else if args.is_empty() {
                                words.push((std::mem::take(&mut current), glob));
                                glob = false;
                            } else {
                                current.push_str(&args[0]);
                                words.push((std::mem::take(&mut current), glob));
                                glob = false;
                                for a in &args[1..] {
                                    words.push((a.clone(), false));
                                }
                            }
                        } else {
                            if !current.is_empty() {
                                words.push((std::mem::take(&mut current), glob));
                                glob = false;
                            }
                            if args.is_empty() {
                                words.push((String::new(), false));
                            }
                            for a in &args {
                                for f in split_ws(a) {
                                    words.push((f, false));
                                }
                            }
                        }
                        continue;
                    }
                    let value = self.expand_param(name, op, ctx)?;
                    if *quoted {
                        current.push_str(&value);
                    } else {
                        if !current.is_empty() {
                            words.push((std::mem::take(&mut current), glob));
                            glob = false;
                        }
                        for f in split_ws(&value) {
                            words.push((f, false));
                        }
                    }
                }
                Span::ArrayParameter { name, index, quoted } => {
                    let idx = self.evaluate_expr(index);
                    let value = match self.get_var(name) {
                        Some(var) if idx >= 0 => var.value_at(idx as usize).unwrap_or("").to_owned(),
                        _ => String::new(),
                    };
                    if *quoted {
                        current.push_str(&value);
                    } else {
                        if !current.is_empty() {
                            words.push((std::mem::take(&mut current), glob));
                            glob = false;
                        }
                        for f in split_ws(&value) {
                            words.push((f, false));
                        }
                    }
                }
                Span::Command { body, quoted } => {
                    let output = self.run_command_substitution(body, ctx);
                    if *quoted {
                        current.push_str(&output);
                    } else {
                        if !current.is_empty() {
                            words.push((std::mem::take(&mut current), glob));
                            glob = false;
                        }
                        for f in split_ws(&output) {
                            words.push((f, false));
                        }
                    }
                }
                Span::ProcSubst { body, output } => {
                    if *output {
                        crate::panic_at("src/expand.rs:238:25", "not implemented");
                    }
                    let fd = self.run_proc_subst(body, ctx);
                    current.push_str(&format!("/dev/fd/{}", fd));
                }
            }
        }
        if !current.is_empty() || words.is_empty() {
            words.push((current, glob));
        }
        Ok(words)
    }

    fn get_special_or_var(&self, name: &str) -> Option<String> {
        match name {
            "?" => Some(self.last_status.to_string()),
            "$" => Some(process::getpid().as_raw().to_string()),
            "!" => Some(self.last_back_pid.to_string()),
            "#" => {
                let n = (1..=9).filter(|i| self.args().get(*i - 1).is_some()).count();
                Some(n.to_string())
            }
            "-" => Some(String::new()),
            "0" => Some(self.script_name.clone()),
            "@" | "*" => Some(self.args().join(" ")),
            _ => {
                if let Ok(n) = name.parse::<usize>() {
                    return Some(self.args().get(n - 1).cloned().unwrap_or_default());
                }
                self.get_var(name).map(|v| v.as_str().to_owned())
            }
        }
    }

    fn is_special(name: &str) -> bool {
        matches!(name, "?" | "$" | "!" | "#" | "-" | "@" | "*")
    }

    fn expand_param(&mut self, name: &str, op: &ExpansionOp, ctx: &Context) -> Result<String, ExpandError> {
        let value = self.get_special_or_var(name);
        if Self::is_special(name) {
            return Ok(value.unwrap_or_default());
        }
        match op {
            ExpansionOp::Length => Ok(value.map(|v| v.chars().count()).unwrap_or(0).to_string()),
            ExpansionOp::GetOrEmpty => {
                match value {
                    Some(v) => Ok(v),
                    None => {
                        if self.nounset {
                            print_err(&format!("nsh: undefined variable `{}'", name));
                            self.exit(1);
                        }
                        Ok(String::new())
                    }
                }
            }
            ExpansionOp::GetOrDefault(default) | ExpansionOp::GetNullableOrDefault(default) => match value {
                Some(v) => Ok(v),
                None => self.expand_word_into_string(default, ctx),
            },
            ExpansionOp::GetOrDefaultAndAssign(default)
            | ExpansionOp::GetNullableOrDefaultAndAssign(default) => match value {
                Some(v) => Ok(v),
                None => {
                    let v = self.expand_word_into_string(default, ctx)?;
                    self.set_str(name, &v);
                    Ok(v)
                }
            },
            ExpansionOp::Subst {
                pattern,
                replacement,
                replace_all,
            } => {
                let value = value.unwrap_or_default();
                let pat = self.word_to_pattern(pattern, ctx, false);
                let rep = self.word_to_pattern(replacement, ctx, true);
                Ok(pat.replace(&value, &rep, *replace_all))
            }
        }
    }

    /// Converts a word into a pattern. Literal spans of a replacement are
    /// emitted rather than matched.
    pub fn word_to_pattern(&mut self, word: &Word, ctx: &Context, replacement: bool) -> Pattern {
        let mut spans = Vec::new();
        for span in &word.0 {
            match span {
                Span::Literal(s) => {
                    if replacement {
                        spans.push(PatternSpan::Emit(s.clone()));
                    } else {
                        spans.push(PatternSpan::Literal(s.clone()));
                    }
                }
                Span::AnyString => spans.push(PatternSpan::AnyString),
                Span::AnyChar => spans.push(PatternSpan::AnyChar),
                other => {
                    let w = Word(vec![other.clone()]);
                    let s = self.expand_word_into_string(&w, ctx).unwrap_or_default();
                    if !s.is_empty() {
                        spans.push(PatternSpan::Literal(s));
                    }
                }
            }
        }
        Pattern { spans }
    }

    fn run_command_substitution(&mut self, body: &[Term], ctx: &Context) -> String {
        let (r, w) = process::pipe();
        use std::io::Write;
        let _ = std::io::stdout().flush();
        match process::fork() {
            Some(ForkResult::Child) => {
                process::close(r);
                let child_ctx = Context {
                    stdin: ctx.stdin,
                    stdout: w,
                    stderr: ctx.stderr,
                    pgid: None,
                    background: false,
                    interactive: ctx.interactive,
                };
                self.interactive = false;
                let status = self.run_terms(body, &child_ctx);
                let code = match status {
                    ExitStatus::ExitedWith(c) => c,
                    _ => 0,
                };
                self.exit(code);
            }
            Some(ForkResult::Parent { child }) => {
                process::close(w);
                let mut output = Vec::new();
                let mut buf = [0u8; 4096];
                loop {
                    match nix::unistd::read(r, &mut buf) {
                        Ok(0) => break,
                        Ok(n) => output.extend_from_slice(&buf[..n]),
                        Err(nix::Error::EINTR) => continue,
                        Err(_) => break,
                    }
                }
                process::close(r);
                let _ = process::wait_pid(child);
                let mut s = match String::from_utf8(output) {
                    Ok(s) => s,
                    Err(e) => crate::panic_at(
                        "src/utils.rs:43:42",
                        &format!("binary data is not yet supported: {:?}", e),
                    ),
                };
                while s.ends_with('\n') {
                    s.pop();
                }
                s
            }
            None => String::new(),
        }
    }

    fn run_proc_subst(&mut self, body: &[Term], ctx: &Context) -> RawFd {
        let (r, w) = process::pipe();
        use std::io::Write;
        let _ = std::io::stdout().flush();
        match process::fork() {
            Some(ForkResult::Child) => {
                process::close(r);
                let child_ctx = Context {
                    stdin: ctx.stdin,
                    stdout: w,
                    stderr: ctx.stderr,
                    pgid: None,
                    background: false,
                    interactive: ctx.interactive,
                };
                self.interactive = false;
                let status = self.run_terms(body, &child_ctx);
                let code = match status {
                    ExitStatus::ExitedWith(c) => c,
                    _ => 0,
                };
                self.exit(code);
            }
            Some(ForkResult::Parent { .. }) => {
                process::close(w);
                r
            }
            None => r,
        }
    }

    // ------------------------------------------------------------------
    // Arithmetic
    // ------------------------------------------------------------------
    pub fn evaluate_expr(&mut self, expr: &Expr) -> i32 {
        match expr {
            Expr::Literal(n) => *n,
            Expr::Parameter { name } => self.get_str(name).parse::<i32>().unwrap_or(0),
            Expr::Inc(name) => {
                let v = self.get_str(name).parse::<i32>().unwrap_or(0).wrapping_add(1);
                self.set_str(name, &v.to_string());
                v
            }
            Expr::Dec(name) => {
                let v = self.get_str(name).parse::<i32>().unwrap_or(0).wrapping_sub(1);
                self.set_str(name, &v.to_string());
                v
            }
            Expr::Assign { name, rhs } => {
                let v = self.evaluate_expr(rhs);
                self.set_str(name, &v.to_string());
                v
            }
            Expr::Binary(op, lhs, rhs) => {
                let l = self.evaluate_expr(lhs);
                let r = self.evaluate_expr(rhs);
                match op {
                    BinaryExpr::Add => l.wrapping_add(r),
                    BinaryExpr::Sub => l.wrapping_sub(r),
                    BinaryExpr::Mul => l.wrapping_mul(r),
                    BinaryExpr::Div => {
                        if r == 0 {
                            crate::panic_at("src/eval.rs:38:47", "attempt to divide by zero");
                        }
                        l.wrapping_div(r)
                    }
                    BinaryExpr::Eq => (l == r) as i32,
                    BinaryExpr::Ne => (l != r) as i32,
                    BinaryExpr::Lt => (l < r) as i32,
                    BinaryExpr::Le => (l <= r) as i32,
                    BinaryExpr::Gt => (l > r) as i32,
                    BinaryExpr::Ge => (l >= r) as i32,
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // Misc
    // ------------------------------------------------------------------
    pub fn run_file(&mut self, path: &Path, ctx: &Context) -> i32 {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                print_err(&format!("nsh: failed open the file: {:?}", e));
                return 1;
            }
        };
        match parser::parse(&content) {
            Ok(ast) => {
                let status = self.run_ast(&ast, ctx);
                match status {
                    ExitStatus::ExitedWith(c) => c,
                    ExitStatus::Return => crate::panic_at("src/main.rs:133:14", "unexpected Return"),
                    ExitStatus::Break => crate::panic_at("src/main.rs:133:14", "unexpected Break"),
                    ExitStatus::Continue => crate::panic_at("src/main.rs:133:14", "unexpected Continue"),
                    ExitStatus::Running(_) => 0,
                }
            }
            Err(err) => {
                print_err(&format!("nsh: parse error: {}", err));
                -1
            }
        }
    }
}
