fn report_clap_error(prefix: &str, err: ClapError) -> i32 {
    match err {
        ClapError::Info(text) => {
            print_err(&format!("{}{}", prefix, text));
            1
        }
        ClapError::Error(text) => {
            print_err(&format!("{}{}", prefix, text));
            1
        }
    }
}

