fn builtin_alias(shell: &mut Shell, args: &[String]) -> i32 {
    if args.len() < 2 {
        let mut out = String::new();
        for (name, body) in &shell.aliases {
            out.push_str(&format!("{}='{}'\n", name, body));
        }
        print!("{}", out);
        use std::io::Write;
        let _ = std::io::stdout().flush();
        return 0;
    }
    match crate::alias_parser::parse_alias(&args[1]) {
        Ok((name, body)) => {
            if let Some(entry) = shell.aliases.iter_mut().find(|(n, _)| *n == name) {
                entry.1 = body;
            } else {
                shell.aliases.push((name, body));
            }
            0
        }
        Err(err) => {
            print_err(&format!("nsh: alias: {}", err));
            1
        }
    }
}

