fn chdir(shell: &mut Shell, dir: &PathBuf, prefix: &str) -> i32 {
    match std::env::set_current_dir(dir) {
        Ok(()) => 0,
        Err(err) => {
            print_err(&format!("nsh: {}: {}: `{}'", prefix, err, dir.display()));
            1
        }
    }
}

fn builtin_cd(shell: &mut Shell, args: &[String]) -> i32 {
    let cwd = shell.current_dir();
    let dir = match args.get(1) {
        None => {
            shell.dir_stack.push(cwd);
            match dirs::home_dir() {
                Some(home) => home,
                None => return 1,
            }
        }
        Some(arg) if arg == "-" => match shell.dir_stack.pop() {
            Some(dir) => dir,
            None => return 1,
        },
        Some(arg) => {
            shell.dir_stack.push(cwd.clone());
            cwd.join(arg)
        }
    };
    chdir(shell, &dir, "cd")
}

