fn builtin_export(shell: &mut Shell, args: &[String]) -> i32 {
    for arg in &args[1..] {
        if let Some(idx) = arg.find('=') {
            let name = &arg[..idx];
            let value = &arg[idx + 1..];
            shell.set_global_str(name, value);
            shell.export(name);
            if name == "PATH" {
                shell.rebuild_path_table();
            }
        } else {
            shell.export(arg);
        }
    }
    0
}

