    for job in &shell.jobs {
        let state = if job.is_stopped() { "stopped" } else { "running" };
        out.push_str(&format!("[{}] {}: {}\n", job.id, state, job.cmd));
    }
    print!("{}", out);
    use std::io::Write;
    let _ = std::io::stdout().flush();
    0
}

fn parse_job_id(shell: &Shell, arg: Option<&str>) -> Result<usize, i32> {
    match arg {
        Some(arg) => {
            if let Some(num) = arg.strip_prefix('%') {
                match num.parse::<usize>() {
                    Ok(id) if shell.jobs.iter().any(|j| j.id == id) => Ok(id),
                    _ => {
                        print_err(&format!("nsh: no such job `{}'", num));
                        Err(1)
                    }
                }
            } else {
                print_err(&format!("nsh: invalid job id `{}'", arg));
                Err(1)
            }
        }
        None => match shell.last_fore_job.filter(|id| shell.jobs.iter().any(|j| j.id == *id)) {
            Some(id) => Ok(id),
            None => match shell.jobs.last() {
                Some(job) => Ok(job.id),
                None => {
                    print_err("nsh: no jobs to run");
                    Err(1)
                }
            },
        },
    }
}

const FG_APP: App = App {
    name: "fg",
