        Ok(m) => m,
        Err(e) => return report_clap_error("nsh: fg: ", e),
    };
    let id = match parse_job_id(shell, matches.value_of("job_id")) {
        Ok(id) => id,
        Err(code) => return code,
    };
    continue_job(shell, id, true, ctx)
}

