//! Builtin commands.
use crate::clap2::{self, App, ClapError, FlagSpec, OptSpec, PosSpec};
use crate::shell::{print_err, write_to_fd, Context, ExitStatus, Shell};
use crate::variable::Value;
use std::os::unix::io::RawFd;
use std::path::PathBuf;

pub fn is_builtin(name: &str) -> bool {
    matches!(
        name,
        "alias"
            | "bg"
            | "cd"
            | "echo"
            | "eval"
            | "exec"
            | "exit"
            | "export"
            | "fg"
            | "jobs"
            | "popd"
            | "pushd"
            | "read"
            | "set"
            | "shift"
            | "source"
            | "unset"
            | "wait"
    )
}

pub fn run_builtin(shell: &mut Shell, args: &[String], ctx: &Context) -> ExitStatus {
    let name = args[0].as_str();
    let status = match name {
        "alias" => builtin_alias(shell, args),
        "bg" => builtin_bg(shell, args, ctx),
        "cd" => builtin_cd(shell, args),
        "echo" => builtin_echo(args, ctx),
        "eval" => return builtin_eval(shell, args, ctx),
        "exec" => builtin_exec(shell, args, ctx),
        "exit" => builtin_exit(shell, args),
        "export" => builtin_export(shell, args),
        "fg" => builtin_fg(shell, args, ctx),
        "jobs" => builtin_jobs(shell, args),
        "popd" => builtin_popd(shell, args),
        "pushd" => builtin_pushd(shell, args),
        "read" => builtin_read(shell, args, ctx),
        "set" => builtin_set(shell, args),
        "shift" => builtin_shift(shell, args),
        "source" => return builtin_source(shell, args, ctx),
        "unset" => builtin_unset(shell, args),
        "wait" => builtin_wait(shell, args, ctx),
        _ => 1,
    };
    ExitStatus::ExitedWith(status)
}

fn report_clap_error(prefix: &str, err: ClapError) -> i32 {
    match err {
        ClapError::Info(text) => {
            print_err(&format!("{}{}", prefix, text));
            1
        }
        ClapError::Error(text) => {
            print_err(&format!("{}{}", prefix, text));
            1
        }
    }
}

// ----------------------------------------------------------------------
// alias
// ----------------------------------------------------------------------
fn builtin_alias(shell: &mut Shell, args: &[String]) -> i32 {
    if args.len() < 2 {
        let mut out = String::new();
        for (name, body) in &shell.aliases {
            out.push_str(&format!("{}='{}'\n", name, body));
        }
        print!("{}", out);
        use std::io::Write;
        let _ = std::io::stdout().flush();
        return 0;
    }
    match crate::alias_parser::parse_alias(&args[1]) {
        Ok((name, body)) => {
            if let Some(entry) = shell.aliases.iter_mut().find(|(n, _)| *n == name) {
                entry.1 = body;
            } else {
                shell.aliases.push((name, body));
            }
            0
        }
        Err(err) => {
            print_err(&format!("nsh: alias: {}", err));
            1
        }
    }
}

// ----------------------------------------------------------------------
// cd / pushd / popd
// ----------------------------------------------------------------------
fn chdir(shell: &mut Shell, dir: &PathBuf, prefix: &str) -> i32 {
    match std::env::set_current_dir(dir) {
        Ok(()) => 0,
        Err(err) => {
            print_err(&format!("nsh: {}: {}: `{}'", prefix, err, dir.display()));
            1
        }
    }
}

fn builtin_cd(shell: &mut Shell, args: &[String]) -> i32 {
    let cwd = shell.current_dir();
    let dir = match args.get(1) {
        None => {
            shell.dir_stack.push(cwd);
            match dirs::home_dir() {
                Some(home) => home,
                None => return 1,
            }
        }
        Some(arg) if arg == "-" => match shell.dir_stack.pop() {
            Some(dir) => dir,
            None => return 1,
        },
        Some(arg) => {
            shell.dir_stack.push(cwd.clone());
            cwd.join(arg)
        }
    };
    chdir(shell, &dir, "cd")
}

