// ----------------------------------------------------------------------
// echo
// ----------------------------------------------------------------------
fn builtin_echo(args: &[String], ctx: &Context) -> i32 {
    let mut newline = true;
    let mut escapes = false;
    let mut start = 1;
    if let Some(first) = args.get(1) {
        match first.as_str() {
            "-n" => {
                newline = false;
                start = 2;
            }
            "-e" => {
                escapes = true;
                start = 2;
            }
            "-ne" | "-en" => {
                newline = false;
                escapes = true;
                start = 2;
            }
            _ => {}
        }
    }
    let mut out = String::new();
    for (i, arg) in args[start..].iter().enumerate() {
        if i > 0 {
            out.push(' ');
        }
        if escapes {
            out.push_str(&arg.replace("\\n", "\n").replace("\\t", "\t"));
        } else {
            out.push_str(arg);
        }
    }
    if newline {
        out.push('\n');
    }
    write_to_fd(ctx.stdout, &out);
    0
}

// ----------------------------------------------------------------------
// eval / source / exec / exit
// ----------------------------------------------------------------------
fn builtin_eval(shell: &mut Shell, args: &[String], ctx: &Context) -> ExitStatus {
    if args.len() < 2 {
        return ExitStatus::ExitedWith(0);
    }
    let script = args[1..].join(" ");
    let mut ctx2 = *ctx;
    ctx2.background = false;
    shell.run_script(&script, &ctx2)
}

fn builtin_source(shell: &mut Shell, args: &[String], ctx: &Context) -> ExitStatus {
    match args.get(1) {
        Some(path) => {
            let mut ctx2 = *ctx;
            ctx2.background = false;
            let status = shell.run_file(std::path::Path::new(path), &ctx2);
            ExitStatus::ExitedWith(status)
        }
        None => {
            print_err("nsh: source: filename argument required");
            ExitStatus::ExitedWith(0)
        }
    }
}

fn builtin_exec(shell: &mut Shell, args: &[String], ctx: &Context) -> i32 {
    if args.len() < 2 {
        return 0;
    }
    let _ = shell;
    use std::io::Write;
    let _ = std::io::stdout().flush();
    if ctx.stdin != 0 {
        crate::process::dup2(ctx.stdin, 0);
    }
    if ctx.stdout != 1 {
        crate::process::dup2(ctx.stdout, 1);
    }
    if ctx.stderr != 2 {
        crate::process::dup2(ctx.stderr, 2);
    }
    let err = crate::process::execvp(&args[1], &args[1..]);
    print_err(&format!("nsh: exec: {}", err));
    127
}

fn builtin_exit(shell: &mut Shell, args: &[String]) -> i32 {
    let status = match args.get(1) {
        Some(arg) => arg.parse::<i32>().unwrap_or(1),
        None => 0,
    };
    shell.exit(status)
}

// ----------------------------------------------------------------------
// export / unset
// ----------------------------------------------------------------------
fn builtin_export(shell: &mut Shell, args: &[String]) -> i32 {
    for arg in &args[1..] {
        if let Some(idx) = arg.find('=') {
            let name = &arg[..idx];
            let value = &arg[idx + 1..];
            shell.set_global_str(name, value);
            shell.export(name);
            if name == "PATH" {
                shell.rebuild_path_table();
            }
        } else {
            shell.export(arg);
        }
    }
    0
}

