    version: "0.4.2",
};

fn read_line_from_fd(fd: RawFd) -> Option<String> {
    let mut buf = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        match nix::unistd::read(fd, &mut byte) {
            Ok(0) => break,
            Ok(_) => {
                if byte[0] == b'\n' {
                    break;
                }
                buf.push(byte[0]);
            }
            Err(nix::Error::EINTR) => continue,
            Err(_) => break,
        }
    }
    if buf.is_empty() {
        return None;
    }
    match String::from_utf8(buf) {
        Ok(s) => Some(s),
        Err(e) => crate::panic_at(
            "src/utils.rs:43:42",
            &format!("binary data is not yet supported: {:?}", e),
        ),
    }
}

fn builtin_read(shell: &mut Shell, args: &[String], ctx: &Context) -> i32 {
    let mut app = READ_APP.clone();
    app.opts = vec![OptSpec {
        short: Some('p'),
        long: None,
        name: "prompt",
        value_name: "prompt",
    }];
    app.positionals = vec![PosSpec {
        name: "VAR",
        required: true,
    }];
    let matches = match clap2::parse(&app, &args[1..]) {
        Ok(m) => m,
        Err(e) => return report_clap_error("read: ", e),
    };
    if let Some(prompt) = matches.value_of("prompt") {
        if nix::unistd::isatty(ctx.stdin).unwrap_or(false) {
            write_to_fd(ctx.stdout, prompt);
        }
    }
    let var = matches.value_of("VAR").unwrap_or("").to_owned();
    match read_line_from_fd(ctx.stdin) {
        Some(line) => {
            let value = line.trim_end().to_owned();
            shell.set_global_str(&var, &value);
            0
        }
        None => 1,
    }
}

