        Err(code) => return code,
    };
    continue_job(shell, id, false, ctx)
}

fn continue_job(shell: &mut Shell, id: usize, foreground: bool, ctx: &Context) -> i32 {
    let (pgid, cmd) = match shell.jobs.iter().find(|j| j.id == id) {
        Some(job) => (job.pgid, job.cmd.clone()),
        None => return 1,
    };
    for job in shell.jobs.iter_mut() {
        if job.id == id {
            for state in job.states.iter_mut() {
                if matches!(state, crate::process::ProcessState::Stopped(_)) {
                    *state = crate::process::ProcessState::Running;
                }
            }
        }
    }
    crate::process::kill_cont(pgid);
    if foreground {
        let mut ctx2 = *ctx;
        ctx2.background = false;
        let status = shell.wait_for_job(id, &ctx2);
        status
    } else {
        println!("[{}] Continued: {}", id, cmd);
        0
    }
}

