fn builtin_wait(shell: &mut Shell, args: &[String], ctx: &Context) -> i32 {
    let mut app = WAIT_APP.clone();
    app.positionals = vec![PosSpec {
        name: "job_id",
        required: false,
    }];
    let matches = match clap2::parse(&app, &args[1..]) {
        Ok(m) => m,
        Err(e) => return report_clap_error("wait: ", e),
    };
    match matches.value_of("job_id") {
        Some(arg) => {
            if let Some(num) = arg.strip_prefix('%') {
                match num.parse::<usize>() {
                    Ok(id) if shell.jobs.iter().any(|j| j.id == id) => {
                        let mut ctx2 = *ctx;
                        ctx2.background = false;
                        shell.wait_for_job(id, &ctx2)
                    }
                    _ => {
                        print_err(&format!("nsh: no such job `{}'", num));
                        1
                    }
                }
            } else {
                print_err(&format!("nsh: invalid job id `{}'", arg));
                1
            }
        }
        None => {
            let ids: Vec<usize> = shell.jobs.iter().map(|j| j.id).collect();
            for id in ids {
                let mut ctx2 = *ctx;
                ctx2.background = false;
                shell.wait_for_job(id, &ctx2);
            }
            shell.check_jobs();
            0
        }
    }
}

