        let code = status_to_code(status);
        let _ = std::io::stdout().flush();
        std::process::exit(code);
    }

    if let Some(file) = opts.file {
        shell.script_name = file.clone();
        let path = std::path::PathBuf::from(&file);
        let content = match std::fs::read_to_string(&path) {
            Ok(c) => c,
            Err(e) => panic_at("src/main.rs:114:34", &format!("failed to open the file: {:?}", e)),
        };
        let code = match parser::parse(&content) {
            Ok(ast) => status_to_code(shell.run_ast(&ast, &ctx)),
            Err(err) => {
                shell::print_err(&format!("nsh: parse error: {}", err));
                255
            }
        };
        let _ = std::io::stdout().flush();
        std::process::exit(code);
    }

    interactive::run(shell, ctx);
}
