//! Command history (~/.nsh_history).
use std::fs::OpenOptions;
use std::io::Write;

pub struct History {
    pub entries: Vec<String>,
    path: Option<std::path::PathBuf>,
}

impl History {
    pub fn load() -> History {
        let path = dirs::home_dir().map(|h| h.join(".nsh_history"));
        let mut entries = Vec::new();
        if let Some(ref p) = path {
            if let Ok(content) = std::fs::read_to_string(p) {
                for line in content.lines() {
                    let mut parts = line.splitn(3, '\t');
                    let _time = parts.next();
                    let _cwd = parts.next();
                    if let Some(cmd) = parts.next() {
                        entries.push(cmd.to_owned());
                    }
                }
            }
        }
        History { entries, path }
    }

    pub fn append(&mut self, cmd: &str, cwd: &str) {
        if cmd.chars().count() < 8 {
            return;
        }
        if self.entries.last().map(|l| l == cmd).unwrap_or(false) {
            return;
        }
        self.entries.push(cmd.to_owned());
        if let Some(ref p) = self.path {
            if let Ok(mut f) = OpenOptions::new().create(true).append(true).open(p) {
                let time = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_secs())
                    .unwrap_or(0);
                let _ = writeln!(f, "{}\t{}\t{}", time, cwd, cmd);
            }
        }
    }
}
