//! Prompt rendering (`$PROMPT`).

pub const DEFAULT_PROMPT: &str = "\\{cyan}\\{bold}\\{current_dir} $\\{reset} ";

pub struct PromptContext {
    pub current_dir: String,
    pub username: String,
    pub hostname: String,
    pub in_repo: bool,
    pub repo_status: String,
    pub in_remote: bool,
}

/// Renders the prompt. Returns the rendered text (with escape sequences).
pub fn render(fmt: &str, ctx: &PromptContext) -> String {
    let mut out = String::new();
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            match chars[i + 1] {
                'n' => {
                    out.push('\n');
                    i += 2;
                    continue;
                }
                '{' => {
                    // \{name}
                    if let Some(end) = find_close(&chars, i + 2) {
                        let name: String = chars[i + 2..end].iter().collect();
                        out.push_str(&expand_name(&name, ctx));
                        i = end + 1;
                        continue;
                    }
                }
                'i' => {
                    // \if{cond}{then}{else}
                    let rest: String = chars[i..].iter().collect();
                    if rest.starts_with("\\if{") {
                        if let Some((cond, then, els, consumed)) = parse_if(&chars[i + 3..]) {
                            let truth = match cond.as_str() {
                                "in_repo" => ctx.in_repo,
                                "in_remote" => ctx.in_remote,
                                _ => false,
                            };
                            if truth {
                                out.push_str(&render(&then, ctx));
                            } else {
                                out.push_str(&render(&els, ctx));
                            }
                            i += 3 + consumed;
                            continue;
                        }
                    }
                }
                _ => {}
            }
            out.push(c);
            i += 1;
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}

fn find_close(chars: &[char], start: usize) -> Option<usize> {
    let mut depth = 0;
    let mut i = start;
    while i < chars.len() {
        match chars[i] {
            '{' => depth += 1,
            '}' => {
                if depth == 0 {
                    return Some(i);
                }
                depth -= 1;
            }
            _ => {}
        }
        i += 1;
    }
    None
}

/// Parses `{cond}{then}{else}` starting at `chars[0] == '{'`.
fn parse_if(chars: &[char]) -> Option<(String, String, String, usize)> {
    let mut parts = Vec::new();
    let mut i = 0;
    for _ in 0..3 {
        if chars.get(i) != Some(&'{') {
            return None;
        }
        let end = find_close(chars, i + 1)?;
        parts.push(chars[i + 1..end].iter().collect::<String>());
        i = end + 1;
    }
    Some((parts[0].clone(), parts[1].clone(), parts[2].clone(), i))
}

fn expand_name(name: &str, ctx: &PromptContext) -> String {
    match name {
        "reset" => "\x1b[0m".to_owned(),
        "bold" => "\x1b[1m".to_owned(),
        "underline" => "\x1b[4m".to_owned(),
        "red" => "\x1b[31m".to_owned(),
        "green" => "\x1b[32m".to_owned(),
        "yellow" => "\x1b[33m".to_owned(),
        "blue" => "\x1b[34m".to_owned(),
        "magenta" => "\x1b[35m".to_owned(),
        "cyan" => "\x1b[36m".to_owned(),
        "current_dir" => ctx.current_dir.clone(),
        "username" => ctx.username.clone(),
        "hostname" => ctx.hostname.clone(),
        "repo_status" => ctx.repo_status.clone(),
        _ => String::new(),
    }
}

/// Returns the display width of the prompt (ignoring escape sequences).
pub fn display_width(s: &str) -> usize {
    let mut width = 0;
    let mut in_escape = false;
    for c in s.chars() {
        if in_escape {
            if c.is_ascii_alphabetic() {
                in_escape = false;
            }
            continue;
        }
        if c == '\x1b' {
            in_escape = true;
            continue;
        }
        width += 1;
    }
    width
}
