            || self.shell.functions.contains_key(name)
            || self.shell.aliases.iter().any(|(n, _)| n == name)
            || self.shell.path_table.contains_key(name)
            || ((name.starts_with('/') || name.starts_with("./")) && std::path::Path::new(name).exists())
    }

