        let prefix = self.prefix();
        if is_keyword(&word) {
            self.out.push_str(&format!("{}{}{}{}", prefix, BOLD, word, RESET));
        } else if self.cmd_pos {
            let color = if self.command_exists(word.trim_end_matches('=').trim_end()) {
                GREEN
            } else {
                RED
            };
            self.out.push_str(&format!("{}{}{}{}", prefix, color, word, RESET));
            self.cmd_pos = false;
        } else if word.starts_with('-') && !self.in_quote {
            self.out.push_str(&format!("{}{}{}{}", prefix, YELLOW, word, RESET));
        } else {
            self.out.push_str(&format!("{}{}", prefix, word));
        }
    }

    fn emit_op(&mut self, op: &str) {
