                            self.pos += 1;
                        }
                        if self.in_quote {
                            self.out.push_str(&format!("{}{}{}${{{}{}{}", CYAN, BOLD, GREEN, CYAN, name, RESET));
                        } else {
                            self.out.push_str(&format!("{}{}${{{}{}", BOLD, GREEN, name, RESET));
                        }
                        // operator part
                        if self.chars.get(self.pos) == Some(&':') {
                            self.out.push_str(&format!("{}{}", BOLD, RESET));
                            let mut op = String::new();
                            while self.pos < self.chars.len() && (self.chars[self.pos] == ':' || self.chars[self.pos] == '-' || self.chars[self.pos] == '=') {
                                op.push(self.chars[self.pos]);
                                self.pos += 1;
                            }
                            self.out.push_str(&format!("{}{}", op, RESET));
                        } else if self.chars.get(self.pos) == Some(&'#') {
                            self.pos += 1;
                        }
                        // Content until the closing brace.
                        let saved_cmd = self.cmd_pos;
                        self.cmd_pos = false;
                        self.in_brace(depth);
                        self.cmd_pos = saved_cmd;
                    } else {
                        let mut name = String::from("$");
                        while self.pos < self.chars.len() && is_name_char(self.chars[self.pos]) {
                            name.push(self.chars[self.pos]);
                            self.pos += 1;
                        }
                        self.out.push_str(&format!("{}{}{}{}", self.prefix(), BOLD, name, RESET));
                    }
                }
                ')' if depth > 0 => {
                    self.flush_word();
                    self.out.push_str(&format!("{}{}){}", self.prefix(), GREEN, RESET));
                    self.pos += 1;
                    return;
                }
                _ => {
                    self.word.push(c);
                    self.pos += 1;
                }
            }
        }
        self.flush_word();
        if self.in_quote && self.chars.last() != Some(&'"') && self.chars.last() != Some(&'\'') {
            // pending (possibly empty) literal at EOF
        }
    }

    fn in_brace(&mut self, depth: usize) {
        let mut text = String::new();
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c == '}' {
                if !text.is_empty() {
                    self.out.push_str(&format!("{}{}", self.prefix(), text));
                    text.clear();
                }
                self.out.push_str(&format!("{}{}}}{}", self.prefix(), GREEN, RESET));
                self.pos += 1;
                return;
            }
            if c == '$' || c == '"' || c == '\'' {
                if !text.is_empty() {
                    self.out.push_str(&format!("{}{}", self.prefix(), text));
                    text.clear();
                }
                // Delegate a single token to the main loop.
                let saved_word = std::mem::take(&mut self.word);
                let end = self.scan_single_token(depth);
                self.word = saved_word;
                if !end {
                    return;
                }
                continue;
            }
            text.push(c);
            self.pos += 1;
        }
        if !text.is_empty() {
            self.out.push_str(&format!("{}{}", self.prefix(), text));
        }
    }

    /// Handles one `$...` or quoted token at the current position. Returns false
    /// when the input ended.
    fn scan_single_token(&mut self, depth: usize) -> bool {
        let c = self.chars[self.pos];
        if c == '$' {
            // Reuse the main loop for exactly one token by temporarily
            // limiting the input.
            let start = self.pos;
            let mut end = start + 1;
            if self.chars.get(end) == Some(&'(') {
                // find matching paren
                let mut d = 0;
                while end < self.chars.len() {
                    if self.chars[end] == '(' {
                        d += 1;
                    } else if self.chars[end] == ')' {
                        d -= 1;
                        if d == 0 {
                            end += 1;
                            break;
                        }
                    }
                    end += 1;
                }
            } else if self.chars.get(end) == Some(&'{') {
                while end < self.chars.len() && self.chars[end] != '}' {
                    end += 1;
                }
                if end < self.chars.len() {
                    end += 1;
                }
            } else {
                while end < self.chars.len() && is_name_char(self.chars[end]) {
                    end += 1;
                }
            }
            let saved: Vec<char> = self.chars.clone();
            self.chars = saved[..end].to_vec();
            self.run(depth);
            self.chars = saved;
            self.pos = end;
            return self.pos < self.chars.len();
        }
        // quote toggle
        self.flush_word();
        if self.in_quote {
            self.out.push_str(&format!("{}{}{}", CYAN, c, RESET));
            self.in_quote = false;
        } else {
            self.in_quote = true;
            self.out.push_str(&format!("{}{}", CYAN, c));
        }
        self.pos += 1;
        self.pos < self.chars.len()
    }
}
