enum Key {
    Char(char),
    Enter,
    Backspace,
    Delete,
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    CtrlA,
    CtrlC,
    CtrlD,
    CtrlE,
    CtrlK,
    CtrlL,
    CtrlR,
    CtrlW,
    CtrlU,
    Tab,
    AltF,
    AltB,
    AltQ,
    Unknown,
}

fn read_key(stdin: &mut std::io::Stdin) -> Option<Key> {
    let mut buf = [0u8; 1];
    let n = stdin.read(&mut buf).ok()?;
    if n == 0 {
        return None;
    }
    let b = buf[0];
    let key = match b {
        b'\r' | b'\n' => Key::Enter,
        0x7f | 0x08 => Key::Backspace,
        0x01 => Key::CtrlA,
        0x03 => Key::CtrlC,
        0x04 => Key::CtrlD,
        0x05 => Key::CtrlE,
        0x0b => Key::CtrlK,
        0x0c => Key::CtrlL,
        0x12 => Key::CtrlR,
        0x17 => Key::CtrlW,
        0x15 => Key::CtrlU,
        b'\t' => Key::Tab,
        0x1b => {
            let mut b2 = [0u8; 1];
            if stdin.read(&mut b2).ok()? == 0 {
                return Some(Key::Unknown);
            }
            match b2[0] {
                b'[' => {
                    let mut seq = Vec::new();
                    loop {
                        let mut b3 = [0u8; 1];
                        if stdin.read(&mut b3).ok()? == 0 {
                            return Some(Key::Unknown);
                        }
                        seq.push(b3[0]);
                        if (0x40..=0x7e).contains(&b3[0]) {
                            break;
                        }
                    }
                    match seq.as_slice() {
                        b"A" => Key::Up,
                        b"B" => Key::Down,
                        b"C" => Key::Right,
                        b"D" => Key::Left,
                        b"H" => Key::Home,
                        b"F" => Key::End,
                        b"3~" => Key::Delete,
                        b"1;3C" => Key::AltF,
                        b"1;3D" => Key::AltB,
                        _ => Key::Unknown,
                    }
                }
                b'f' => Key::AltF,
                b'b' => Key::AltB,
                b'q' => Key::AltQ,
                _ => Key::Unknown,
            }
        }
        _ => {
            // UTF-8 decoding
            let width = if b < 0x80 {
                1
            } else if b >> 5 == 0x6 {
                2
            } else if b >> 4 == 0xe {
                3
            } else {
                4
            };
            let mut bytes = vec![b];
            for _ in 1..width {
                let mut bb = [0u8; 1];
                if stdin.read(&mut bb).ok()? == 0 {
                    break;
                }
                bytes.push(bb[0]);
            }
            match String::from_utf8(bytes) {
                Ok(s) => Key::Char(s.chars().next().unwrap_or(' ')),
                Err(_) => Key::Unknown,
            }
        }
    };
    Some(key)
}

pub fn run(mut shell: Shell, ctx: Context) {
    let terminal = Terminal::new();
    crate::process::ignore_shell_signals();
    // Put the shell in its own process group and take the terminal.
    let pid = nix::unistd::getpid();
    let _ = nix::unistd::setpgid(pid, pid);
    shell.shell_pgid = pid;
    crate::process::set_terminal_pgid(0, pid);

    let mut history = History::load();
    let mut stdin = std::io::stdin();

    loop {
        shell.check_jobs();
        let prompt_text = render_prompt(&shell);
        let cols = terminal_columns();
        let mut out = String::new();
        out.push_str("\x1b[1m\x1b[7m$\x1b[0m");
        for _ in 0..cols.saturating_sub(1) {
            out.push(' ');
        }
        out.push('\r');
        out.push_str(&prompt_text);
        write_out(&out);
        let prompt_width = prompt::display_width(prompt_text.rsplit('\n').next().unwrap_or(""));

        terminal.enter_raw();
        let mut editor = Editor {
            input: Vec::new(),
            cursor: 0,
            history_index: None,
            saved_input: Vec::new(),
        };
        editor.render(&shell, prompt_width);
        let mut line: Option<String> = None;
        loop {
            let key = match read_key(&mut stdin) {
                Some(k) => k,
                None => {
                    terminal.restore();
                    write_out("\r\n");
                    shell.exit(0);
                }
            };
            match key {
                Key::Enter => {
                    editor.render(&shell, prompt_width);
                    line = Some(editor.input.iter().collect());
                    break;
                }
                Key::Char(c) => editor.insert(c),
                Key::Backspace => editor.backspace(),
                Key::Delete => editor.delete(),
                Key::Left => {
                    if editor.cursor > 0 {
                        editor.cursor -= 1;
                    }
                }
                Key::Right => {
                    if editor.cursor < editor.input.len() {
                        editor.cursor += 1;
                    }
                }
                Key::Home | Key::CtrlA => editor.cursor = 0,
                Key::End | Key::CtrlE => editor.cursor = editor.input.len(),
                Key::CtrlC => {
                    editor.render(&shell, prompt_width);
                    write_out("\r\n");
                    line = Some(String::new());
                    break;
                }
                Key::CtrlD => {}
                Key::CtrlK => editor.kill_to_end(),
                Key::CtrlU => {
                    editor.input.drain(..editor.cursor);
                    editor.cursor = 0;
                }
                Key::CtrlL => {
                    write_out("\x1b[2J\x1b[H");
                    let mut out = String::new();
                    out.push_str(&prompt_text);
                    write_out(&out);
                }
                Key::CtrlW => editor.delete_word(),
                Key::AltF => editor.next_word(),
                Key::AltB => editor.prev_word(),
                Key::AltQ => {
                    editor.saved_input = std::mem::take(&mut editor.input);
                    editor.cursor = 0;
                }
                Key::Up => {
                    let len = history.entries.len();
                    let next = match editor.history_index {
                        None if len > 0 => Some(len - 1),
                        Some(i) if i > 0 => Some(i - 1),
                        other => other,
                    };
                    if let Some(i) = next {
                        if editor.history_index.is_none() {
                            editor.saved_input = editor.input.clone();
                        }
                        editor.history_index = Some(i);
                        editor.input = history.entries[i].chars().collect();
                        editor.cursor = editor.input.len();
                    }
                }
                Key::Down => {
                    if let Some(i) = editor.history_index {
                        if i + 1 < history.entries.len() {
                            editor.history_index = Some(i + 1);
                            editor.input = history.entries[i + 1].chars().collect();
                        } else {
                            editor.history_index = None;
                            editor.input = std::mem::take(&mut editor.saved_input);
                        }
                        editor.cursor = editor.input.len();
                    }
                }
                Key::Tab | Key::CtrlR | Key::Unknown => {}
            }
            editor.render(&shell, prompt_width);
        }
        terminal.restore();
        if let Some(line) = line {
            if line.trim().is_empty() {
                write_out("\r\n");
                continue;
            }
            write_out("\r\n");
            let status = shell.run_script(&line, &ctx);
            let cwd = shell.current_dir().display().to_string();
            history.append(&line, &cwd);
            match status {
                ExitStatus::ExitedWith(_) | ExitStatus::Running(_) => {}
                ExitStatus::Break => crate::panic_at("src/main.rs:133:14", "unexpected Break"),
                ExitStatus::Continue => crate::panic_at("src/main.rs:133:14", "unexpected Continue"),
                ExitStatus::Return => crate::panic_at("src/main.rs:133:14", "unexpected Return"),
            }
        }
    }
}
