p='/workspace/src/highlight.rs'
s=open(p).read()
s=s.replace('''                ' ' if !self.in_quote => {
                    self.flush_word();
                    self.out.push(' ');
                    self.pos += 1;
                }''','''                ' ' if !self.in_quote => {
                    self.flush_word();
                    self.out.push(' ');
                    self.pos += 1;
                }
                ' ' if self.in_quote && self.word.is_empty() => {
                    self.out.push_str(&format!("{} ", CYAN));
                    self.pos += 1;
                }''')
s=s.replace('''                    } else if self.chars.get(self.pos) == Some(&'{') {
                        self.pos += 1;
                        let mut name = String::new();''','''                    } else if self.chars.get(self.pos) == Some(&'{') {
                        self.pos += 1;
                        if self.chars.get(self.pos) == Some(&'#') {
                            // `${#x}`: the `#` is dropped.
                            self.pos += 1;
                        }
                        let mut name = String::new();''')
s=s.replace('''                ')' if depth > 0 => {
                    self.flush_word();
                    self.out.push_str(&format!("{}{}){}", self.prefix(), GREEN, RESET));
                    self.pos += 1;
                    return;
                }''','''                ')' if depth > 0 => {
                    self.flush_word();
                    self.out.push_str(&format!("{}{}){}", self.prefix(), GREEN, RESET));
                    self.pos += 1;
                    return;
                }''')
s=s.replace('''        if depth == 0 && self.in_quote && self.word.is_empty() {
            // The pending (empty) literal inside quotes is emitted at EOF.
            self.out.push_str(CYAN);
            return;
        }
        self.flush_word();
    }''','''        if depth > 0 {
            self.eof_in_subst = true;
        }
        if depth == 0 && self.in_quote && self.word.is_empty() && !self.eof_in_subst {
            // The pending (empty) literal inside quotes is emitted at EOF.
            self.out.push_str(CYAN);
            return;
        }
        self.flush_word();
    }''')
s=s.replace('''    cmd_pos: bool,
    word: String,
}''','''    cmd_pos: bool,
    word: String,
    eof_in_subst: bool,
}''')
s=s.replace('''            cmd_pos: true,
            word: String::new(),
        };''','''            cmd_pos: true,
            word: String::new(),
            eof_in_subst: false,
        };''')
open(p,'w').write(s)
EOF
