//! Tab completion.
use crate::shell::Shell;

/// Returns true if `query` is a subsequence of `name`.
fn fuzzy_match(name: &str, query: &str) -> bool {
    let mut it = name.chars();
    for q in query.chars() {
        loop {
            match it.next() {
                Some(c) if c == q => break,
                Some(_) => continue,
                None => return false,
            }
        }
    }
    true
}

fn score(name: &str, query: &str) -> (u8, usize) {
    if name == query {
        (0, name.len())
    } else if name.starts_with(query) {
        (1, name.len())
    } else if name.contains(query) {
        (2, name.len())
    } else {
        (3, name.len())
    }
}

pub fn complete_command(shell: &Shell, query: &str) -> Vec<String> {
    let mut candidates: Vec<String> = Vec::new();
    for b in [
        "alias", "bg", "cd", "echo", "eval", "exec", "exit", "export", "fg", "jobs", "popd", "pushd", "read", "set",
        "shift", "source", "unset", "wait",
    ] {
        if fuzzy_match(b, query) {
            candidates.push(b.to_owned());
        }
    }
    for (name, _) in &shell.aliases {
        if fuzzy_match(name, query) {
            candidates.push(name.clone());
        }
    }
    for name in shell.functions.keys() {
        if fuzzy_match(name, query) {
            candidates.push(name.clone());
        }
    }
    let mut paths: Vec<String> = shell
        .path_table
        .keys()
        .filter(|n| fuzzy_match(n, query))
        .cloned()
        .collect();
    paths.sort();
    candidates.extend(paths);
    candidates.sort_by(|a, b| score(a, query).cmp(&score(b, query)).then_with(|| a.cmp(b)));
    candidates
}

pub fn complete_path(query: &str) -> Vec<String> {
    let expanded = if let Some(rest) = query.strip_prefix('~') {
        match dirs::home_dir() {
            Some(h) => format!("{}{}", h.display(), rest),
            None => query.to_owned(),
        }
    } else {
        query.to_owned()
    };
    let (dir, prefix) = match expanded.rfind('/') {
        Some(idx) => (&expanded[..=idx], &expanded[idx + 1..]),
        None => ("", expanded.as_str()),
    };
    let read_dir = if dir.is_empty() { "." } else { dir };
    let mut result = Vec::new();
    if let Ok(entries) = std::fs::read_dir(read_dir) {
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            if !name.starts_with(prefix) {
                continue;
            }
            if name.starts_with('.') && !prefix.starts_with('.') {
                continue;
            }
            result.push(format!("{}{}", dir, name));
        }
    }
    result.sort();
    result
}
EOF
echo ok"}

