    word_start: usize,
    word_end: usize,
    /// Number of menu rows currently displayed.
    rows: usize,
}

fn terminal_rows() -> usize {
    let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
    let r = unsafe { libc::ioctl(0, libc::TIOCGWINSZ, &mut ws) };
    if r == 0 && ws.ws_row > 0 {
        ws.ws_row as usize
    } else {
        24
    }
}

impl Completion {
    /// Renders the menu below the input line. The cursor must be at the end
    /// of the input line (after a render). Returns the menu text.
    fn render_menu(&mut self, prompt_width: usize, cursor: usize) -> String {
        let cols = terminal_columns();
        let max_rows = terminal_rows().saturating_sub(1).max(1);
        let max_len = self.candidates.iter().map(|c| c.chars().count()).max().unwrap_or(0);
        let columns = (cols / (max_len + 4)).max(1);
        let width = cols / columns;
        let total_rows = (self.candidates.len() + columns - 1) / columns;
        let shown_rows = total_rows.min(max_rows);
        let mut out = String::new();
        out.push_str("\\r\\n");
        for row in 0..shown_rows {
            for col in 0..columns {
                let idx = row * columns + col;
                if idx >= self.candidates.len() {
                    break;
                }
                let name = &self.candidates[idx];
                let len = name.chars().count();
                if idx == self.selected {
                    out.push_str(&format!("\\x1b[7m{}\\x1b[27m", name));
                } else {
                    out.push_str(&format!("{}\\x1b[0m", name));
                }
                if width > len {
                    out.push_str(&format!("\\x1b[{}C", width - len));
                }
            }
            if row + 1 < shown_rows {
                out.push_str("\\r\\n");
            }
        }
        let mut rows = shown_rows;
        if total_rows > shown_rows {
            let remaining = self.candidates.len() - shown_rows * columns;
            out.push_str(&format!("\\x1b[K\\r\\n\\x1b[7m {} more \\x1b[0m", remaining));
            rows += 1;
        }
        out.push_str(&format!("\\x1b[{}A\\r\\x1b[{}C\\x1b[?25h", rows, prompt_width + cursor));
        self.rows = rows;
        out
    }

    fn clear_menu(&self) -> String {
        let mut out = String::new();
        for _ in 0..self.rows {
            out.push_str("\\x1b[1B\\x1b[2K");
        }
        out.push_str(&format!("\\x1b[{}A", self.rows));
        out
    }
}''')

