        let mut after_list = false;
        for inner in pair.into_inner() {
            match inner.as_rule() {
                Rule::and_or_list => {
                    let code = inner.as_str().trim_end().to_owned();
                    let pipelines = self.build_and_or_list(inner);
                    terms.push(Term {
                        code,
                        pipelines,
                        background: false,
                    });
